insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (366, 44, 1, 16, 'سورة الدخان ١ – ١٦', 'الدخان: إنا أنزلناه في ليلة مباركة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 366) = $j$[{"lbl": "الآيات ١ – ٨", "q": "حمٓ ﴿١﴾ وَٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ ﴿٣﴾ فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ ﴿٤﴾ أَمۡرٗا مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ ﴿٥﴾ رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦﴾ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ ﴿٧﴾ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿٨﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["والكتاب المبين", "القرآن المظهر للحلال والحرام في الأقوال والأعمال."], ["إنا أنزلناه في ليلة مباركة", "في ليلة القدر من رمضان."], ["فيها يُفرق كل أمر حكيم", "يُفصل كل أمر محكم من الآجال والأرزاق وسائر الأحداث."], ["أمراً من عندنا", "أمرنا بذلك أمراً من عندنا."], ["إنا كنا مرسلين رحمة من ربك", "مرسلين الرسل، محمداً ومن قبله، رحمة من ربك بالمرسل إليهم من الأمم والشعوب."], ["إنه هو السميع العليم", "السميع لأصوات مخلوقاته، العليم بحاجاتهم."], ["إن كنتم موقنين", "بأنه رب السماوات والأرض، فآمنوا برسوله واعبدوه وحده."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا لمثله فائدتين في أول غافر. والكتاب المبين: قسم أقسم الله به بالقرآن تنويهاً بشأنه، ولله أن يقسم بما شاء، وإنما الحجر على الإنسان أن يحلف بغير ربه. إنا أنزلنا القرآن في ليلة كثيرة البركة والخير، هي ليلة القدر التي هي خير من ألف شهر، إنا كنا منذرين، ولذلك أرسلنا الرسول وأنزلنا القرآن لننذر الناس عذاب يوم القيامة حيث لا ينجي منه إلا الإيمان والعمل الصالح، ولا يُعرفان إلا بالوحي. في تلك الليلة المباركة يُفصل كل أمر محكم مما قضى الله أن يتم في تلك السنة من أحداث، يؤخذ من كتاب المقادير فيُنفّذ خلال السنة: من الموت والحياة، والغنى والفقر، والصحة والمرض، والتولية والعزل، حتى إن الرجل ليتزوج ويولد له وهو في عداد من يموت، فلا تنتهي السنة إلا وقد مات. أمراً من عندنا أمرنا به، إنا كنا مرسلين الرسل محمداً فمن قبله رحمة من ربك بالناس، إنه هو السميع لأصواتهم العليم بحاجاتهم، فكان إرسال الرسل رحمة من ربك فاحمده واشكره. رب السماوات والأرض وما بينهما إن كنتم موقنين بذلك فاعبدوه وحده، لا إله إلا هو يحيي ويميت، ربكم ورب آبائكم الأولين. بل هم في شك يلعبون: إقرارهم بأن الله رب السماوات لم يكن عن يقين، إذ لو كان لما أنكروا توحيده، فهم يلعبون بالأقوال كما يلعبون بالأفعال، مقلّدون لآبائهم في ذلك.", "h": ["بيان فضل ليلة القدر وأنها في رمضان.", "تقرير عقيدة القضاء والقدر وإثبات اللوح المحفوظ.", "إرسال الرسل رحمة من الله بعباده، فلم يكن زمن الفترة وأهلها أفضل من زمن الوحي.", "لم يكن إقرار المشركين بربوبية الله تعالى لخلقه عن علم يقيني، بل هم مقلّدون فيه، فلذا لم يحملهم على توحيد الله في عبادته، وهذا شأن كل علم أو معتقد ضعيف."], "k": "«فيها يُفرق كل أمر حكيم»… تُكتب فيها أقدار سنتي؛ فكيف أستقبلها؟"}, {"lbl": "الآيات ٩ – ١٦", "q": "بَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ ﴿٩﴾ فَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ ﴿١٠﴾ يَغۡشَى ٱلنَّاسَۖ هَٰذَا عَذَابٌ أَلِيمٞ ﴿١١﴾ رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ ﴿١٢﴾ أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولٞ مُّبِينٞ ﴿١٣﴾ ثُمَّ تَوَلَّوۡاْ عَنۡهُ وَقَالُواْ مُعَلَّمٞ مَّجۡنُونٌ ﴿١٤﴾ إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ إِنَّكُمۡ عَآئِدُونَ ﴿١٥﴾ يَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰٓ إِنَّا مُنتَقِمُونَ ﴿١٦﴾", "w": [["بل هم في شك يلعبون", "ليسوا بموقنين، بل هم في شك من ربوبية الله يلعبون بالأقوال والأفعال، مقلّدون لآبائهم."], ["فارتقب", "انتظر."], ["بدخان مبين", "ما كان يراه الرجل من قريش لشدة الجوع بين السماء والأرض."], ["يغشى الناس", "يغشى أبصارهم من شدة الجهد الناتج عن الجوع الشديد."], ["ربنا اكشف عنا العذاب", "يا ربنا إن كشفت عنا العذاب آمنا بك وبرسولك."], ["أنّى لهم الذكرى", "من أي وجه يكون لهم التذكّر وقد جاءهم رسول مبين فتولّوا عنه؟"], ["معلَّم مجنون", "يعلّمه القرآن بشر، مجنون مختلط عليه أمره."], ["إنكم عائدون", "إلى الكفر والجحود."], ["البطشة الكبرى", "الأخذة القوية التي أخذناهم بها يوم بدر حيث قُتلوا وأُسروا."]], "m": "نزلت بعد أن دعا رسول الله ﷺ على قريش يوم كثر استهزاؤهم به فقال: «اللهم اجعلها عليهم سنين كسني يوسف»، أي سبع سنين من القحط، فأمره ربه أن ينتظر ذلك: فارتقب يوم تأتي السماء بدخان مبين يغشى الناس هذا عذاب أليم. واستجاب الله لرسوله فأصاب قريشاً قحط وجدب ماتت فيه مواشيهم، وأصابهم جوع أكلوا فيه العهن وشربوا الدم، وكان الرجل يرفع رأسه إلى السماء فلا يرى إلا دخاناً يغشى بصره من شدة الجوع، حتى ضرعوا إلى الله وبعثوا إلى الرسول يطلبون أن يدعو الله برفع العذاب: ربنا اكشف عنا العذاب إنا مؤمنون. ومن أين يأتيهم التذكّر وقد جاءهم رسول مبيّن للحق فعرفوا أنه رسول صدق، ثم أعرضوا عنه وقالوا: معلَّم يعلّمه غيره، ومجنون؟ فتذكّرهم وتوبتهم مستبعدة جداً. إنا كاشفو العذاب قليلاً إنكم عائدون: وفعلاً كشف الله عنهم عذاب المخمصة ونزل الغيث وسعدت بلادهم بعد شقاء دام سبع سنوات، فعادوا إلى الشرك وحرب الإسلام والمسلمين. وارتقب يوم نبطش البطشة الكبرى إنا منتقمون، وكان ذلك ببدر حيث انتقم الله منهم فقتل صناديدهم وأسر من أسر، وكانت بطشة لم تعرفها قريش قط.", "h": ["صدق وعد الله لرسوله واستجابة دعائه ﷺ.", "الإيمان عند معاينة العذاب لا يجدي ولا ينفع.", "بيان ما قابلت به قريش دعوة الإسلام من جحود وكفران.", "إخبار القرآن بالغيب وصدقه في ذلك آية أنه وحي الله وكلامه."], "k": "«إنا كاشفو العذاب قليلاً إنكم عائدون»… كم مرة رُفع عني البلاء فعدت إلى ما كنت عليه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 366;
insert into public.tdb_cards(topic, i, body) select 366, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٨", "q": "حمٓ ﴿١﴾ وَٱلۡكِتَٰبِ ٱلۡمُبِينِ ﴿٢﴾ إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ ﴿٣﴾ فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ ﴿٤﴾ أَمۡرٗا مِّنۡ عِندِنَآۚ إِنَّا كُنَّا مُرۡسِلِينَ ﴿٥﴾ رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٦﴾ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ ﴿٧﴾ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ ﴿٨﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["والكتاب المبين", "القرآن المظهر للحلال والحرام في الأقوال والأعمال."], ["إنا أنزلناه في ليلة مباركة", "في ليلة القدر من رمضان."], ["فيها يُفرق كل أمر حكيم", "يُفصل كل أمر محكم من الآجال والأرزاق وسائر الأحداث."], ["أمراً من عندنا", "أمرنا بذلك أمراً من عندنا."], ["إنا كنا مرسلين رحمة من ربك", "مرسلين الرسل، محمداً ومن قبله، رحمة من ربك بالمرسل إليهم من الأمم والشعوب."], ["إنه هو السميع العليم", "السميع لأصوات مخلوقاته، العليم بحاجاتهم."], ["إن كنتم موقنين", "بأنه رب السماوات والأرض، فآمنوا برسوله واعبدوه وحده."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا لمثله فائدتين في أول غافر. والكتاب المبين: قسم أقسم الله به بالقرآن تنويهاً بشأنه، ولله أن يقسم بما شاء، وإنما الحجر على الإنسان أن يحلف بغير ربه. إنا أنزلنا القرآن في ليلة كثيرة البركة والخير، هي ليلة القدر التي هي خير من ألف شهر، إنا كنا منذرين، ولذلك أرسلنا الرسول وأنزلنا القرآن لننذر الناس عذاب يوم القيامة حيث لا ينجي منه إلا الإيمان والعمل الصالح، ولا يُعرفان إلا بالوحي. في تلك الليلة المباركة يُفصل كل أمر محكم مما قضى الله أن يتم في تلك السنة من أحداث، يؤخذ من كتاب المقادير فيُنفّذ خلال السنة: من الموت والحياة، والغنى والفقر، والصحة والمرض، والتولية والعزل، حتى إن الرجل ليتزوج ويولد له وهو في عداد من يموت، فلا تنتهي السنة إلا وقد مات. أمراً من عندنا أمرنا به، إنا كنا مرسلين الرسل محمداً فمن قبله رحمة من ربك بالناس، إنه هو السميع لأصواتهم العليم بحاجاتهم، فكان إرسال الرسل رحمة من ربك فاحمده واشكره. رب السماوات والأرض وما بينهما إن كنتم موقنين بذلك فاعبدوه وحده، لا إله إلا هو يحيي ويميت، ربكم ورب آبائكم الأولين. بل هم في شك يلعبون: إقرارهم بأن الله رب السماوات لم يكن عن يقين، إذ لو كان لما أنكروا توحيده، فهم يلعبون بالأقوال كما يلعبون بالأفعال، مقلّدون لآبائهم في ذلك.", "h": ["بيان فضل ليلة القدر وأنها في رمضان.", "تقرير عقيدة القضاء والقدر وإثبات اللوح المحفوظ.", "إرسال الرسل رحمة من الله بعباده، فلم يكن زمن الفترة وأهلها أفضل من زمن الوحي.", "لم يكن إقرار المشركين بربوبية الله تعالى لخلقه عن علم يقيني، بل هم مقلّدون فيه، فلذا لم يحملهم على توحيد الله في عبادته، وهذا شأن كل علم أو معتقد ضعيف."], "k": "«فيها يُفرق كل أمر حكيم»… تُكتب فيها أقدار سنتي؛ فكيف أستقبلها؟"}, {"lbl": "الآيات ٩ – ١٦", "q": "بَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ ﴿٩﴾ فَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ ﴿١٠﴾ يَغۡشَى ٱلنَّاسَۖ هَٰذَا عَذَابٌ أَلِيمٞ ﴿١١﴾ رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ ﴿١٢﴾ أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَآءَهُمۡ رَسُولٞ مُّبِينٞ ﴿١٣﴾ ثُمَّ تَوَلَّوۡاْ عَنۡهُ وَقَالُواْ مُعَلَّمٞ مَّجۡنُونٌ ﴿١٤﴾ إِنَّا كَاشِفُواْ ٱلۡعَذَابِ قَلِيلًاۚ إِنَّكُمۡ عَآئِدُونَ ﴿١٥﴾ يَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰٓ إِنَّا مُنتَقِمُونَ ﴿١٦﴾", "w": [["بل هم في شك يلعبون", "ليسوا بموقنين، بل هم في شك من ربوبية الله يلعبون بالأقوال والأفعال، مقلّدون لآبائهم."], ["فارتقب", "انتظر."], ["بدخان مبين", "ما كان يراه الرجل من قريش لشدة الجوع بين السماء والأرض."], ["يغشى الناس", "يغشى أبصارهم من شدة الجهد الناتج عن الجوع الشديد."], ["ربنا اكشف عنا العذاب", "يا ربنا إن كشفت عنا العذاب آمنا بك وبرسولك."], ["أنّى لهم الذكرى", "من أي وجه يكون لهم التذكّر وقد جاءهم رسول مبين فتولّوا عنه؟"], ["معلَّم مجنون", "يعلّمه القرآن بشر، مجنون مختلط عليه أمره."], ["إنكم عائدون", "إلى الكفر والجحود."], ["البطشة الكبرى", "الأخذة القوية التي أخذناهم بها يوم بدر حيث قُتلوا وأُسروا."]], "m": "نزلت بعد أن دعا رسول الله ﷺ على قريش يوم كثر استهزاؤهم به فقال: «اللهم اجعلها عليهم سنين كسني يوسف»، أي سبع سنين من القحط، فأمره ربه أن ينتظر ذلك: فارتقب يوم تأتي السماء بدخان مبين يغشى الناس هذا عذاب أليم. واستجاب الله لرسوله فأصاب قريشاً قحط وجدب ماتت فيه مواشيهم، وأصابهم جوع أكلوا فيه العهن وشربوا الدم، وكان الرجل يرفع رأسه إلى السماء فلا يرى إلا دخاناً يغشى بصره من شدة الجوع، حتى ضرعوا إلى الله وبعثوا إلى الرسول يطلبون أن يدعو الله برفع العذاب: ربنا اكشف عنا العذاب إنا مؤمنون. ومن أين يأتيهم التذكّر وقد جاءهم رسول مبيّن للحق فعرفوا أنه رسول صدق، ثم أعرضوا عنه وقالوا: معلَّم يعلّمه غيره، ومجنون؟ فتذكّرهم وتوبتهم مستبعدة جداً. إنا كاشفو العذاب قليلاً إنكم عائدون: وفعلاً كشف الله عنهم عذاب المخمصة ونزل الغيث وسعدت بلادهم بعد شقاء دام سبع سنوات، فعادوا إلى الشرك وحرب الإسلام والمسلمين. وارتقب يوم نبطش البطشة الكبرى إنا منتقمون، وكان ذلك ببدر حيث انتقم الله منهم فقتل صناديدهم وأسر من أسر، وكانت بطشة لم تعرفها قريش قط.", "h": ["صدق وعد الله لرسوله واستجابة دعائه ﷺ.", "الإيمان عند معاينة العذاب لا يجدي ولا ينفع.", "بيان ما قابلت به قريش دعوة الإسلام من جحود وكفران.", "إخبار القرآن بالغيب وصدقه في ذلك آية أنه وحي الله وكلامه."], "k": "«إنا كاشفو العذاب قليلاً إنكم عائدون»… كم مرة رُفع عني البلاء فعدت إلى ما كنت عليه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (367, 44, 17, 33, 'سورة الدخان ١٧ – ٣٣', 'الدخان: فما بكت عليهم السماء والأرض', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 367) = $j$[{"lbl": "الآيات ١٧ – ٢٤", "q": "۞وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ ﴿١٧﴾ أَنۡ أَدُّوٓاْ إِلَيَّ عِبَادَ ٱللَّهِۖ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٨﴾ وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِۖ إِنِّيٓ ءَاتِيكُم بِسُلۡطَٰنٖ مُّبِينٖ ﴿١٩﴾ وَإِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ ﴿٢٠﴾ وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ ﴿٢١﴾ فَدَعَا رَبَّهُۥٓ أَنَّ هَـٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ ﴿٢٢﴾ فَأَسۡرِ بِعِبَادِي لَيۡلًا إِنَّكُم مُّتَّبَعُونَ ﴿٢٣﴾ وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندٞ مُّغۡرَقُونَ ﴿٢٤﴾", "w": [["ولقد فتنّا قبلهم قوم فرعون", "اختبرنا قبل كفار قريش قوم فرعون من القبط."], ["وجاءهم رسول كريم", "موسى بن عمران ﵇."], ["أن أدّوا إليّ عباد الله", "ادفعوا إليّ عباد الله بني إسرائيل وأرسلوهم معي."], ["إني لكم رسول أمين", "رسول الله إليكم أمين على وحيه ورسالته."], ["وأن لا تعلوا على الله", "لا تطغوا على الله فتكفروا به وتعصوه."], ["بسلطان مبين", "بحجة واضحة تدل على صدقي في رسالتي."], ["وإني عذت بربي وربكم أن ترجمون", "اعتصمت بربي وربكم واستجرت به أن ترجموني."], ["وإن لم تؤمنوا لي فاعتزلون", "إن لم تصدّقوني فخلّوا سبيلي واتركوني."], ["فدعا ربه", "لما كذّبه فرعون وقومه وهمّوا بقتله نادى ربه: يا رب."], ["إن هؤلاء قوم مجرمون", "مجرمون بالكفر والظلم."], ["فأسرِ بعبادي ليلاً إنكم متّبعون", "فأجابه ربه: فأسرِ بعبادي بني إسرائيل ليلاً، إن فرعون وجنده متّبعوكم ليردّوكم."], ["واترك البحر رهواً", "إذا اجتزت أنت وقومك البحر فاتركه ساكناً كما هو حين دخلته."], ["إنهم جند مغرقون", "إن فرعون وقومه جند والله مغرقهم في البحر."]], "m": "هذا شروع في قصة موسى مع فرعون، لوجود تشابه بين أكابر مجرمي قريش وبين فرعون في ظلمه وعلوّه، والقصد تسلية الرسول ﷺ وتخفيف ألمه النفسي: ولقد اختبرنا قبل كفار قريش قوم فرعون من القبط، وجاءهم رسول كريم على ربه وعلى قومه، هو موسى بن عمران ﵇: أن ادفعوا إليّ عباد الله بني إسرائيل وأرسلوهم معي، إني لكم رسول أمين على رسالتي صادق في قولي، ولا تطغوا على الله فتكفروا به وتعصوه، إني آتيكم بحجة بيّنة، وإني استجرت بربي وربكم وتحصّنت به أن ترجموني بأقوالكم أو أعمالكم، وإن لم تصدّقوا بما جئتكم به فاعتزلوني. ولما أبوا إلا أذاه وأرادوا قتله دعا ربه: رب إن هؤلاء قوم مجرمون كفرة ظلمة، فأوحى إليه ربه: فأسرِ بعبادي بني إسرائيل ليلاً في آخر الليل، وأعلمه أن فرعون وجنوده متّبعون لهم ليردّوهم وينكّلوا بهم. ولما ضرب موسى البحر بعصاه فانفلق فلقتين ودخله بنو إسرائيل فاجتازوه، أراد أن يضرب البحر ليلتئم كما كان حتى لا يدخله فرعون وجنده فيدركوهم، فقال له ربه: اترك البحر ساكناً كما كان حين دخلتموه، حتى إذا دخل فرعون وجنوده أطبقناه عليهم، إنهم جند مغرقون؛ وهذا الذي حصل، فنجّى الله موسى وبني إسرائيل وأغرق فرعون وجنوده أجمعين.", "h": ["وجود تشابه كبير بين فرعون وكفار قريش في العلو والصلف والكفر والظلم.", "مشروعية الاعتبار بما سلف من أحداث في الكون، والائتساء بالصالحين.", "وجوب الاستعاذة بالله تعالى والاستجارة به، إذ لا مجير على الحقيقة إلا هو ولا واقي سواه.", "مشروعية دعاء الله تعالى على الظالمين، وسؤاله النصر عليهم والنجاة منهم."], "k": "«واترك البحر رهواً إنهم جند مغرقون»… أراد موسى أن يغلق البحر، وكان تدبير الله أحكم؛ فهل أثق في تدبيره حين يخالف تدبيري؟"}, {"lbl": "الآيات ٢٥ – ٣٣", "q": "كَمۡ تَرَكُواْ مِن جَنَّـٰتٖ وَعُيُونٖ ﴿٢٥﴾ وَزُرُوعٖ وَمَقَامٖ كَرِيمٖ ﴿٢٦﴾ وَنَعۡمَةٖ كَانُواْ فِيهَا فَٰكِهِينَ ﴿٢٧﴾ كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ ﴿٢٨﴾ فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ ﴿٢٩﴾ وَلَقَدۡ نَجَّيۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِينِ ﴿٣٠﴾ مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِيٗا مِّنَ ٱلۡمُسۡرِفِينَ ﴿٣١﴾ وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ ﴿٣٢﴾ وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَـٰٓؤٞاْ مُّبِينٌ ﴿٣٣﴾", "w": [["كم تركوا من جنات", "بساتين وحدائق غنّاء."], ["ومقام كريم", "مجالس حسنة ومحافل مزيّنة ومنازل حسنة."], ["ونعمة كانوا فيها فاكهين", "نضرة عيش ولذاذة كانوا فيها ناعمين."], ["وأورثناها قوماً آخرين", "بني إسرائيل."], ["فما بكت عليهم السماء والأرض", "لهوانهم على الله بسبب كفرهم وظلمهم."], ["وما كانوا منظَرين", "ممهلين حتى يتوبوا."], ["من العذاب المهين", "قتل أبنائهم واستخدام نسائهم."], ["ولقد اخترناهم على علم على العالمين", "اخترناهم على علم منا على عالمي زمانهم من الإنس والجن، لكثرة الأنبياء منهم وفيهم."], ["من الآيات ما فيه بلاء مبين", "أعطيناهم من النعم ما فيه اختبار واضح، كانفلاق البحر والمنّ والسلوى."]], "m": "ما زال السياق في قصة موسى ﵇ مع فرعون: كم ترك فرعون وجنوده الذين هلكوا معه في البحر من بساتين وعيون جارية تُسقى بها الزروع، ومنازل حسنة ومحافل مزيّنة، ومتعة عظيمة كانوا فيها ناعمين مترفين؛ هكذا كانت نعمتهم فسلبناها منهم لكفرهم بنا وتعاليهم على شرائعنا وأوليائنا، وأورثناها قوماً آخرين هم بنو إسرائيل إذ رجعوا إلى مصر بعد هلاك فرعون. فما بكت عليهم السماء والأرض لأنهم كانوا كافرين لم يعملوا على الأرض خيراً ولم يعرج إلى السماء من عملهم خير، إنما يبكي المسلمَ الأرضُ التي كان يسجد عليها ويعبد الله فوقها، والسماءُ التي كان يصعد إليها عمله الصالح كل يوم وليلة. وما كانوا ممهلين، بل عاجلهم الرب بالعقوبة لعلمه بطبع قلوبهم، وكم واعدوا موسى إن رُفع عنهم العذاب يؤمنون وما آمنوا. ولقد نجّينا بني إسرائيل من العذاب المهين الذي كان فرعون وقومه يصبّونه عليهم، إذ كانوا يذبحون أبناءهم ويستحيون نساءهم للخدمة والامتهان، إنه كان جباراً طاغياً من المسرفين في الكفر والظلم. ولقد اخترناهم على علم منا على عالمي زمانهم من الثقلين، وآتيناهم من الآيات ما فيه اختبار عظيم، كانفلاق البحر وتظليل الغمام لهم والمنّ والسلوى في التيه، أيشكرون أم يكفرون؟", "h": ["بيان سنة الله في سلب النعم وإنزال النقم بمن كفر نعم الله ولم يشكرها فعصى ربه وأطاع هواه ونفسه، فترك الصلاة واتبع الشهوات، وترك القرآن واشتغل بالأغاني، وأعرض عن ذكر الله وأقبل على ذكر الدنيا ومفاتنها.", "بيان هوان أهل الكفر والفسق على الله وعلى الكون كله، وكرامة أهل الإيمان والتقوى على الله وعلى الكون كله، حتى إن السماء والأرض تبكيهم إذا ماتوا.", "ذمّ العلو في الأرض، وهو التكبر والإسراف في كل شيء.", "بيان أن الله يبتلي، أي يختبر، عباده بالخير والشر."], "k": "«فما بكت عليهم السماء والأرض»… أي بقعة من الأرض ستبكيني لأني سجدت عليها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 367;
insert into public.tdb_cards(topic, i, body) select 367, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٧ – ٢٤", "q": "۞وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ ﴿١٧﴾ أَنۡ أَدُّوٓاْ إِلَيَّ عِبَادَ ٱللَّهِۖ إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ﴿١٨﴾ وَأَن لَّا تَعۡلُواْ عَلَى ٱللَّهِۖ إِنِّيٓ ءَاتِيكُم بِسُلۡطَٰنٖ مُّبِينٖ ﴿١٩﴾ وَإِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ ﴿٢٠﴾ وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ ﴿٢١﴾ فَدَعَا رَبَّهُۥٓ أَنَّ هَـٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ ﴿٢٢﴾ فَأَسۡرِ بِعِبَادِي لَيۡلًا إِنَّكُم مُّتَّبَعُونَ ﴿٢٣﴾ وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندٞ مُّغۡرَقُونَ ﴿٢٤﴾", "w": [["ولقد فتنّا قبلهم قوم فرعون", "اختبرنا قبل كفار قريش قوم فرعون من القبط."], ["وجاءهم رسول كريم", "موسى بن عمران ﵇."], ["أن أدّوا إليّ عباد الله", "ادفعوا إليّ عباد الله بني إسرائيل وأرسلوهم معي."], ["إني لكم رسول أمين", "رسول الله إليكم أمين على وحيه ورسالته."], ["وأن لا تعلوا على الله", "لا تطغوا على الله فتكفروا به وتعصوه."], ["بسلطان مبين", "بحجة واضحة تدل على صدقي في رسالتي."], ["وإني عذت بربي وربكم أن ترجمون", "اعتصمت بربي وربكم واستجرت به أن ترجموني."], ["وإن لم تؤمنوا لي فاعتزلون", "إن لم تصدّقوني فخلّوا سبيلي واتركوني."], ["فدعا ربه", "لما كذّبه فرعون وقومه وهمّوا بقتله نادى ربه: يا رب."], ["إن هؤلاء قوم مجرمون", "مجرمون بالكفر والظلم."], ["فأسرِ بعبادي ليلاً إنكم متّبعون", "فأجابه ربه: فأسرِ بعبادي بني إسرائيل ليلاً، إن فرعون وجنده متّبعوكم ليردّوكم."], ["واترك البحر رهواً", "إذا اجتزت أنت وقومك البحر فاتركه ساكناً كما هو حين دخلته."], ["إنهم جند مغرقون", "إن فرعون وقومه جند والله مغرقهم في البحر."]], "m": "هذا شروع في قصة موسى مع فرعون، لوجود تشابه بين أكابر مجرمي قريش وبين فرعون في ظلمه وعلوّه، والقصد تسلية الرسول ﷺ وتخفيف ألمه النفسي: ولقد اختبرنا قبل كفار قريش قوم فرعون من القبط، وجاءهم رسول كريم على ربه وعلى قومه، هو موسى بن عمران ﵇: أن ادفعوا إليّ عباد الله بني إسرائيل وأرسلوهم معي، إني لكم رسول أمين على رسالتي صادق في قولي، ولا تطغوا على الله فتكفروا به وتعصوه، إني آتيكم بحجة بيّنة، وإني استجرت بربي وربكم وتحصّنت به أن ترجموني بأقوالكم أو أعمالكم، وإن لم تصدّقوا بما جئتكم به فاعتزلوني. ولما أبوا إلا أذاه وأرادوا قتله دعا ربه: رب إن هؤلاء قوم مجرمون كفرة ظلمة، فأوحى إليه ربه: فأسرِ بعبادي بني إسرائيل ليلاً في آخر الليل، وأعلمه أن فرعون وجنوده متّبعون لهم ليردّوهم وينكّلوا بهم. ولما ضرب موسى البحر بعصاه فانفلق فلقتين ودخله بنو إسرائيل فاجتازوه، أراد أن يضرب البحر ليلتئم كما كان حتى لا يدخله فرعون وجنده فيدركوهم، فقال له ربه: اترك البحر ساكناً كما كان حين دخلتموه، حتى إذا دخل فرعون وجنوده أطبقناه عليهم، إنهم جند مغرقون؛ وهذا الذي حصل، فنجّى الله موسى وبني إسرائيل وأغرق فرعون وجنوده أجمعين.", "h": ["وجود تشابه كبير بين فرعون وكفار قريش في العلو والصلف والكفر والظلم.", "مشروعية الاعتبار بما سلف من أحداث في الكون، والائتساء بالصالحين.", "وجوب الاستعاذة بالله تعالى والاستجارة به، إذ لا مجير على الحقيقة إلا هو ولا واقي سواه.", "مشروعية دعاء الله تعالى على الظالمين، وسؤاله النصر عليهم والنجاة منهم."], "k": "«واترك البحر رهواً إنهم جند مغرقون»… أراد موسى أن يغلق البحر، وكان تدبير الله أحكم؛ فهل أثق في تدبيره حين يخالف تدبيري؟"}, {"lbl": "الآيات ٢٥ – ٣٣", "q": "كَمۡ تَرَكُواْ مِن جَنَّـٰتٖ وَعُيُونٖ ﴿٢٥﴾ وَزُرُوعٖ وَمَقَامٖ كَرِيمٖ ﴿٢٦﴾ وَنَعۡمَةٖ كَانُواْ فِيهَا فَٰكِهِينَ ﴿٢٧﴾ كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا قَوۡمًا ءَاخَرِينَ ﴿٢٨﴾ فَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ ﴿٢٩﴾ وَلَقَدۡ نَجَّيۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِينِ ﴿٣٠﴾ مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِيٗا مِّنَ ٱلۡمُسۡرِفِينَ ﴿٣١﴾ وَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ ﴿٣٢﴾ وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَـٰٓؤٞاْ مُّبِينٌ ﴿٣٣﴾", "w": [["كم تركوا من جنات", "بساتين وحدائق غنّاء."], ["ومقام كريم", "مجالس حسنة ومحافل مزيّنة ومنازل حسنة."], ["ونعمة كانوا فيها فاكهين", "نضرة عيش ولذاذة كانوا فيها ناعمين."], ["وأورثناها قوماً آخرين", "بني إسرائيل."], ["فما بكت عليهم السماء والأرض", "لهوانهم على الله بسبب كفرهم وظلمهم."], ["وما كانوا منظَرين", "ممهلين حتى يتوبوا."], ["من العذاب المهين", "قتل أبنائهم واستخدام نسائهم."], ["ولقد اخترناهم على علم على العالمين", "اخترناهم على علم منا على عالمي زمانهم من الإنس والجن، لكثرة الأنبياء منهم وفيهم."], ["من الآيات ما فيه بلاء مبين", "أعطيناهم من النعم ما فيه اختبار واضح، كانفلاق البحر والمنّ والسلوى."]], "m": "ما زال السياق في قصة موسى ﵇ مع فرعون: كم ترك فرعون وجنوده الذين هلكوا معه في البحر من بساتين وعيون جارية تُسقى بها الزروع، ومنازل حسنة ومحافل مزيّنة، ومتعة عظيمة كانوا فيها ناعمين مترفين؛ هكذا كانت نعمتهم فسلبناها منهم لكفرهم بنا وتعاليهم على شرائعنا وأوليائنا، وأورثناها قوماً آخرين هم بنو إسرائيل إذ رجعوا إلى مصر بعد هلاك فرعون. فما بكت عليهم السماء والأرض لأنهم كانوا كافرين لم يعملوا على الأرض خيراً ولم يعرج إلى السماء من عملهم خير، إنما يبكي المسلمَ الأرضُ التي كان يسجد عليها ويعبد الله فوقها، والسماءُ التي كان يصعد إليها عمله الصالح كل يوم وليلة. وما كانوا ممهلين، بل عاجلهم الرب بالعقوبة لعلمه بطبع قلوبهم، وكم واعدوا موسى إن رُفع عنهم العذاب يؤمنون وما آمنوا. ولقد نجّينا بني إسرائيل من العذاب المهين الذي كان فرعون وقومه يصبّونه عليهم، إذ كانوا يذبحون أبناءهم ويستحيون نساءهم للخدمة والامتهان، إنه كان جباراً طاغياً من المسرفين في الكفر والظلم. ولقد اخترناهم على علم منا على عالمي زمانهم من الثقلين، وآتيناهم من الآيات ما فيه اختبار عظيم، كانفلاق البحر وتظليل الغمام لهم والمنّ والسلوى في التيه، أيشكرون أم يكفرون؟", "h": ["بيان سنة الله في سلب النعم وإنزال النقم بمن كفر نعم الله ولم يشكرها فعصى ربه وأطاع هواه ونفسه، فترك الصلاة واتبع الشهوات، وترك القرآن واشتغل بالأغاني، وأعرض عن ذكر الله وأقبل على ذكر الدنيا ومفاتنها.", "بيان هوان أهل الكفر والفسق على الله وعلى الكون كله، وكرامة أهل الإيمان والتقوى على الله وعلى الكون كله، حتى إن السماء والأرض تبكيهم إذا ماتوا.", "ذمّ العلو في الأرض، وهو التكبر والإسراف في كل شيء.", "بيان أن الله يبتلي، أي يختبر، عباده بالخير والشر."], "k": "«فما بكت عليهم السماء والأرض»… أي بقعة من الأرض ستبكيني لأني سجدت عليها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (368, 44, 34, 59, 'سورة الدخان ٣٤ – ٥٩', 'الدخان: إن يوم الفصل ميقاتهم أجمعين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 368) = $j$[{"lbl": "الآيات ٣٤ – ٤٢", "q": "إِنَّ هَـٰٓؤُلَآءِ لَيَقُولُونَ ﴿٣٤﴾ إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِينَ ﴿٣٥﴾ فَأۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٣٦﴾ أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ﴿٣٧﴾ وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ﴿٣٨﴾ مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٩﴾ إِنَّ يَوۡمَ ٱلۡفَصۡلِ مِيقَٰتُهُمۡ أَجۡمَعِينَ ﴿٤٠﴾ يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ ﴿٤١﴾ إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٤٢﴾", "w": [["إن هؤلاء", "المشركين من قريش."], ["إن هي إلا موتتنا الأولى", "لا حياة بعدها ولا موت، وهذا تكذيب بالبعث."], ["وما نحن بمنشَرين", "بمبعوثين أحياء من قبورنا بعد موتنا."], ["فأتوا بآبائنا إن كنتم صادقين", "ائتِ يا محمد بآبائنا الذين ماتوا إن كنت صادقاً في أننا نُبعث."], ["أهم خير أم قوم تُبّع والذين من قبلهم", "هؤلاء المشركون خير في القوة والمنعة أم قوم تُبّع والذين من قبلهم كعاد؟"], ["أهلكناهم إنهم كانوا مجرمين", "أنزلنا بهم عقوبتنا فأهلكناهم."], ["لاعبين", "عابثين بخلقهما لا لغرض صالح."], ["ما خلقناهما إلا بالحق", "إلا لأمر اقتضى خلقهما، وهو أن أُذكر فيهما وأُشكر."], ["إن يوم الفصل ميقاتهم أجمعين", "يوم القيامة الذي يُفصل فيه بين الخلائق ميعادهم أجمعين."], ["يوم لا يغني مولى عن مولى شيئاً", "لا يكفي قريب قريبه بدفع شيء من العذاب عنه."], ["ولا هم يُنصرون", "لا ينصر بعضهم بعضاً."], ["إلا من رحم الله", "لكن من رحمه الله فإنه يُدفع عنه العذاب ويُنصر."], ["إنه هو العزيز الرحيم", "الغالب المنتقم من أعدائه، الرحيم بأوليائه."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ، فما ذكر قصص موسى وفرعون إلا تذكيراً لهم: إن هؤلاء الهابطين بعقولهم إلى أسوأ المستويات يقولون: ما هي إلا موتتنا الأولى، منكرين البعث ليواصلوا كفرهم وفسقهم، وما نحن بمبعوثين أحياء من قبورنا، فإن أصررتم على قولكم بالحياة الثانية فأتوا بآبائنا الذين ماتوا إن كنتم صادقين؛ وخاطبوه بالجمع شعوراً منهم أنه ليس وحده في هذه الدعوة. أهم خير أم قوم تُبّع والذين من قبلهم؟ ليسوا بخير منهم لا في المال ولا في الرجال، فكما أهلكنا أولئك لإجرامهم نهلك هؤلاء إن لم يتوبوا. وما خلقنا السماوات والأرض وما بينهما عابثين، ما خلقناهما إلا بالحق، ولكن أكثرهم لا يعلمون؛ وهذا دليل على البعث، إذ ليس من الحكمة أن يخلق الله الكون لا لشيء ثم يعدمه ولا شيء وراء ذلك، هذا من العبث الذي يتنزّه عنه العقلاء فكيف بواهب العقول؟ إنما خلقه ليُذكر فيه ويُشكر، فمن ذكره وشكره أكرمه، ومن تركه وكفره أهانه، وذلك يتم يوم القيامة. إن يوم الفصل بين الناس فيما اختلفوا فيه من التوحيد والشرك والبرّ والفجور ميعادهم أجمعين، يوم لا يكفي قريب عن قريبه شيئاً، ولا ينصر بعضهم بعضاً كما كانوا في الدنيا، إلا من رحمه الله في الدنيا بالإيمان والتوحيد فإنه يرحمه في الآخرة، إنه العزيز المنتقم من أعدائه الرحيم بأوليائه.", "h": ["تقرير عقيدة البعث والجزاء.", "الإجرام هو سبب الهلاك والدمار كيفما كان فاعله.", "تُبّع الحِميري كان عبداً صالحاً ملكاً حاكماً، وكان قومه كافرين فأهلكهم الله وأنجاه ومن معه من المؤمنين الصالحين، ففي هذا الملك الصالح عبرة لمن يعتبر.", "تنزّه الرب تعالى عن اللعب والعبث فيما يخلق ويهب، ويأخذ ويعطي ويمنع.", "يوم القيامة، وهو يوم الفصل، ميعاد الخليقة كلها حيث تُجمع لفصل القضاء.", "لا تنفع قرابة ولا خلّة ولا صداقة يوم القيامة، ولكن الإيمان والعمل الصالح."], "k": "«يوم لا يغني مولى عن مولى شيئاً»… من أتّكل عليهم اليوم لن يغنوا عني شيئاً يومها؛ فعلى ماذا أتّكل؟"}, {"lbl": "الآيات ٤٣ – ٥٠", "q": "إِنَّ شَجَرَتَ ٱلزَّقُّومِ ﴿٤٣﴾ طَعَامُ ٱلۡأَثِيمِ ﴿٤٤﴾ كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ ﴿٤٥﴾ كَغَلۡيِ ٱلۡحَمِيمِ ﴿٤٦﴾ خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَآءِ ٱلۡجَحِيمِ ﴿٤٧﴾ ثُمَّ صُبُّواْ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِيمِ ﴿٤٨﴾ ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ ﴿٤٩﴾ إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ ﴿٥٠﴾", "w": [["إن شجرة الزقوم", "الشجرة التي تثمر الزقوم، وهي من أخبث الشجر ثمراً وأشدّه مرارة."], ["طعام الأثيم", "ثمرها طعام الأثيم أبي جهل وأصحابه من ذوي الآثام."], ["كالمهل", "كدُرديّ الزيت الأسود."], ["يغلي في البطون كغلي الحميم", "الماء الشديد الحرارة."], ["خذوه فاعتلوه", "يقال للزبانية: خذوه فجرّوه بغلظة وشدة."], ["إلى سواء الجحيم", "إلى وسطها."], ["ذق إنك أنت العزيز الكريم", "ذق العذاب، إنك كنت تقول: ما بين جبلي مكة أعزّ وأكرم مني."], ["إن هذا ما كنتم به تمترون", "إن هذا العذاب الذي كنتم تشكّون فيه."]], "m": "ما زال السياق في ذكر النار وما فيها من ضروب العذاب: إن شجرة الزقوم، التي تنبت في أصل الجحيم طلعها كأنه رؤوس الشياطين في القبح، وثمرها مرّ أشد المرارة، طعام الأثيم كأبي جهل وأضرابه من ذوي الآثام الكبيرة، كدرديّ الزيت يغلي في بطونهم كغلي الماء الشديد الحرارة. ويقال للزبانية الموكّلين بالنار: خذوه فادفعوه واجذبوه بعنف إلى وسط الجحيم، ثم صبّوا فوق رأسه من عذاب الحميم، ويقال له تهكّماً: ذق إنك أنت العزيز الكريم، كما كنت تقول في الدنيا، إذ كان أبو جهل يقول: ما بين جبلي مكة أعز وأكرم مني، وكان يجمع أولاده ويضع بين أيديهم الزبد وتمر العجوة ويقول لهم: تزقّموا، هذا هو الزقوم الذي يهدّدنا به محمد. إن هذا العذاب الذي كنتم تشكّون في أنه كائن يوم القيامة، لتكذيبكم بالبعث والجزاء.", "h": ["تقرير عقيدة البعث والجزاء.", "عظم عذاب النار وفظاعة ما يلاقيه ذوو الآثام الكبيرة فيها.", "من أشد أنواع العذاب في النار العذاب النفسي بالتهكم والسخرية من المعذَّبين، وهو العذاب المهين الذي يُهين المعذَّبين ويدوس كرامتهم."], "k": "«ذق إنك أنت العزيز الكريم»… الكِبر الذي يرفعني في الدنيا قد يكون هو ما يُذلّني يومها."}, {"lbl": "الآيات ٥١ – ٥٩", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ ﴿٥١﴾ فِي جَنَّـٰتٖ وَعُيُونٖ ﴿٥٢﴾ يَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ ﴿٥٣﴾ كَذَٰلِكَ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ ﴿٥٤﴾ يَدۡعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ ﴿٥٥﴾ لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ ﴿٥٦﴾ فَضۡلٗا مِّن رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٥٧﴾ فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٥٨﴾ فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ ﴿٥٩﴾", "w": [["إن المتقين في مقام أمين", "الذين اتقوا ربهم في الدنيا فآمنوا وعملوا الصالحات بعد اجتناب الشرك والمعاصي في مجلس آمن لا يلحقهم فيه خوف."], ["في جنات وعيون", "هذا هو المقام الأمين."], ["من سندس وإستبرق", "ما رقّ من الديباج وما غلظ منه."], ["متقابلين", "لا ينظر بعضهم إلى قفا بعض لأن الأسرّة تدور بهم."], ["كذلك وزوّجناهم", "الأمر كذلك، وزوّجناهم."], ["بحور عين", "بنساء بيض واسعات الأعين."], ["يدعون فيها بكل فاكهة", "يطلبون من الخدم فيها أن يأتوهم بكل فاكهة."], ["آمنين", "من انقطاعها ومن مضرّاتها ومن كل مخوف."], ["لا يذوقون فيها الموت إلا الموتة الأولى", "لكن الموتة الأولى فقد ذاقوها."], ["فإنما يسّرناه بلسانك", "سهّلنا القرآن بلغتك."], ["لعلهم يتذكرون", "يتعظون فيؤمنون ويوحّدون، لكنهم لا يؤمنون."], ["فارتقب إنهم مرتقبون", "فانتظر هلاكهم فإنهم منتظرون هلاكك."]], "m": "لما ذكر حال أهل النار عقّب بذكر حال أهل الجنة، وهذا أسلوب الترغيب والترهيب الذي تميّز به القرآن لأنه كتاب دعوة وهداية زيادة على أنه كتاب تشريع: إن الذين اتقوه في الدنيا فآمنوا به وأطاعوه ولم يشركوا به في مجلس آمن لا يلحقهم فيه خوف، في بساتين وعيون، يلبسون من الحرير ما رقّ منه وما غلظ، متقابلين على أسرّة تدور بهم، وزوّجناهم بحور عين، والحوراء البيضاء التي في عينيها حَوَر، وهو شدة بياض العين في شدة سوادها، والعيناء الواسعة العينين. يطلبون من الخدم كل فاكهة آمنين من انقطاعها وضررها، لا يذوقون فيها الموت بعد الموتة الأولى التي ذاقوها في الدنيا، فأهلها لا يمرضون ولا يهرمون ولا يموتون، ووقاهم عذاب الجحيم، وهذا دالّ على أن غير المتقين من الموحّدين قد يدخلون النار قبل دخولهم الجنة بخلاف المتقين. فضلاً من ربك، إذ لم يستوجبوه بمجرد تقواهم، وقد قال الرسول ﷺ: «سدّدوا وقاربوا وأبشروا، واعلموا أنه لن يُدخل أحدَكم الجنةَ عملُه»، قالوا: ولا أنت يا رسول الله؟ قال: «ولا أنا إلا أن يتغمّدني الله برحمة منه وفضل». ذلك هو الفوز العظيم: النجاة من النار ودخول الجنة. فإنما سهّلنا القرآن بلغتك العربية لعلهم يتعظون فيؤمنون ويتقون، لكن أكثرهم لم يتعظ، فارتقب ما يحلّ بهم فإنهم منتظرون ما يكون لك من نجاح أو إخفاق.", "h": ["فضل التقوى وكرامة أهلها، والتقوى هي خشية من الله تحمل على طاعة الله بفعل محابّه وترك مكارهه.", "بيان شيء من نعيم أهل الجنة ترغيباً في العمل لها.", "تقرير عقيدة البعث والجزاء.", "بيان الحكمة من تسهيل فهم القرآن الكريم، وهو الاتعاظ المقتضي للتقوى."], "k": "«فضلاً من ربك»… لن يدخلني الجنة عملي وحده؛ فهل أعمل وأنا أرجو فضله لا أتّكل على عملي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 368;
insert into public.tdb_cards(topic, i, body) select 368, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٤ – ٤٢", "q": "إِنَّ هَـٰٓؤُلَآءِ لَيَقُولُونَ ﴿٣٤﴾ إِنۡ هِيَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِينَ ﴿٣٥﴾ فَأۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٣٦﴾ أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ﴿٣٧﴾ وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ﴿٣٨﴾ مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٣٩﴾ إِنَّ يَوۡمَ ٱلۡفَصۡلِ مِيقَٰتُهُمۡ أَجۡمَعِينَ ﴿٤٠﴾ يَوۡمَ لَا يُغۡنِي مَوۡلًى عَن مَّوۡلٗى شَيۡـٔٗا وَلَا هُمۡ يُنصَرُونَ ﴿٤١﴾ إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ﴿٤٢﴾", "w": [["إن هؤلاء", "المشركين من قريش."], ["إن هي إلا موتتنا الأولى", "لا حياة بعدها ولا موت، وهذا تكذيب بالبعث."], ["وما نحن بمنشَرين", "بمبعوثين أحياء من قبورنا بعد موتنا."], ["فأتوا بآبائنا إن كنتم صادقين", "ائتِ يا محمد بآبائنا الذين ماتوا إن كنت صادقاً في أننا نُبعث."], ["أهم خير أم قوم تُبّع والذين من قبلهم", "هؤلاء المشركون خير في القوة والمنعة أم قوم تُبّع والذين من قبلهم كعاد؟"], ["أهلكناهم إنهم كانوا مجرمين", "أنزلنا بهم عقوبتنا فأهلكناهم."], ["لاعبين", "عابثين بخلقهما لا لغرض صالح."], ["ما خلقناهما إلا بالحق", "إلا لأمر اقتضى خلقهما، وهو أن أُذكر فيهما وأُشكر."], ["إن يوم الفصل ميقاتهم أجمعين", "يوم القيامة الذي يُفصل فيه بين الخلائق ميعادهم أجمعين."], ["يوم لا يغني مولى عن مولى شيئاً", "لا يكفي قريب قريبه بدفع شيء من العذاب عنه."], ["ولا هم يُنصرون", "لا ينصر بعضهم بعضاً."], ["إلا من رحم الله", "لكن من رحمه الله فإنه يُدفع عنه العذاب ويُنصر."], ["إنه هو العزيز الرحيم", "الغالب المنتقم من أعدائه، الرحيم بأوليائه."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ، فما ذكر قصص موسى وفرعون إلا تذكيراً لهم: إن هؤلاء الهابطين بعقولهم إلى أسوأ المستويات يقولون: ما هي إلا موتتنا الأولى، منكرين البعث ليواصلوا كفرهم وفسقهم، وما نحن بمبعوثين أحياء من قبورنا، فإن أصررتم على قولكم بالحياة الثانية فأتوا بآبائنا الذين ماتوا إن كنتم صادقين؛ وخاطبوه بالجمع شعوراً منهم أنه ليس وحده في هذه الدعوة. أهم خير أم قوم تُبّع والذين من قبلهم؟ ليسوا بخير منهم لا في المال ولا في الرجال، فكما أهلكنا أولئك لإجرامهم نهلك هؤلاء إن لم يتوبوا. وما خلقنا السماوات والأرض وما بينهما عابثين، ما خلقناهما إلا بالحق، ولكن أكثرهم لا يعلمون؛ وهذا دليل على البعث، إذ ليس من الحكمة أن يخلق الله الكون لا لشيء ثم يعدمه ولا شيء وراء ذلك، هذا من العبث الذي يتنزّه عنه العقلاء فكيف بواهب العقول؟ إنما خلقه ليُذكر فيه ويُشكر، فمن ذكره وشكره أكرمه، ومن تركه وكفره أهانه، وذلك يتم يوم القيامة. إن يوم الفصل بين الناس فيما اختلفوا فيه من التوحيد والشرك والبرّ والفجور ميعادهم أجمعين، يوم لا يكفي قريب عن قريبه شيئاً، ولا ينصر بعضهم بعضاً كما كانوا في الدنيا، إلا من رحمه الله في الدنيا بالإيمان والتوحيد فإنه يرحمه في الآخرة، إنه العزيز المنتقم من أعدائه الرحيم بأوليائه.", "h": ["تقرير عقيدة البعث والجزاء.", "الإجرام هو سبب الهلاك والدمار كيفما كان فاعله.", "تُبّع الحِميري كان عبداً صالحاً ملكاً حاكماً، وكان قومه كافرين فأهلكهم الله وأنجاه ومن معه من المؤمنين الصالحين، ففي هذا الملك الصالح عبرة لمن يعتبر.", "تنزّه الرب تعالى عن اللعب والعبث فيما يخلق ويهب، ويأخذ ويعطي ويمنع.", "يوم القيامة، وهو يوم الفصل، ميعاد الخليقة كلها حيث تُجمع لفصل القضاء.", "لا تنفع قرابة ولا خلّة ولا صداقة يوم القيامة، ولكن الإيمان والعمل الصالح."], "k": "«يوم لا يغني مولى عن مولى شيئاً»… من أتّكل عليهم اليوم لن يغنوا عني شيئاً يومها؛ فعلى ماذا أتّكل؟"}, {"lbl": "الآيات ٤٣ – ٥٠", "q": "إِنَّ شَجَرَتَ ٱلزَّقُّومِ ﴿٤٣﴾ طَعَامُ ٱلۡأَثِيمِ ﴿٤٤﴾ كَٱلۡمُهۡلِ يَغۡلِي فِي ٱلۡبُطُونِ ﴿٤٥﴾ كَغَلۡيِ ٱلۡحَمِيمِ ﴿٤٦﴾ خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَآءِ ٱلۡجَحِيمِ ﴿٤٧﴾ ثُمَّ صُبُّواْ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِيمِ ﴿٤٨﴾ ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ ﴿٤٩﴾ إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ ﴿٥٠﴾", "w": [["إن شجرة الزقوم", "الشجرة التي تثمر الزقوم، وهي من أخبث الشجر ثمراً وأشدّه مرارة."], ["طعام الأثيم", "ثمرها طعام الأثيم أبي جهل وأصحابه من ذوي الآثام."], ["كالمهل", "كدُرديّ الزيت الأسود."], ["يغلي في البطون كغلي الحميم", "الماء الشديد الحرارة."], ["خذوه فاعتلوه", "يقال للزبانية: خذوه فجرّوه بغلظة وشدة."], ["إلى سواء الجحيم", "إلى وسطها."], ["ذق إنك أنت العزيز الكريم", "ذق العذاب، إنك كنت تقول: ما بين جبلي مكة أعزّ وأكرم مني."], ["إن هذا ما كنتم به تمترون", "إن هذا العذاب الذي كنتم تشكّون فيه."]], "m": "ما زال السياق في ذكر النار وما فيها من ضروب العذاب: إن شجرة الزقوم، التي تنبت في أصل الجحيم طلعها كأنه رؤوس الشياطين في القبح، وثمرها مرّ أشد المرارة، طعام الأثيم كأبي جهل وأضرابه من ذوي الآثام الكبيرة، كدرديّ الزيت يغلي في بطونهم كغلي الماء الشديد الحرارة. ويقال للزبانية الموكّلين بالنار: خذوه فادفعوه واجذبوه بعنف إلى وسط الجحيم، ثم صبّوا فوق رأسه من عذاب الحميم، ويقال له تهكّماً: ذق إنك أنت العزيز الكريم، كما كنت تقول في الدنيا، إذ كان أبو جهل يقول: ما بين جبلي مكة أعز وأكرم مني، وكان يجمع أولاده ويضع بين أيديهم الزبد وتمر العجوة ويقول لهم: تزقّموا، هذا هو الزقوم الذي يهدّدنا به محمد. إن هذا العذاب الذي كنتم تشكّون في أنه كائن يوم القيامة، لتكذيبكم بالبعث والجزاء.", "h": ["تقرير عقيدة البعث والجزاء.", "عظم عذاب النار وفظاعة ما يلاقيه ذوو الآثام الكبيرة فيها.", "من أشد أنواع العذاب في النار العذاب النفسي بالتهكم والسخرية من المعذَّبين، وهو العذاب المهين الذي يُهين المعذَّبين ويدوس كرامتهم."], "k": "«ذق إنك أنت العزيز الكريم»… الكِبر الذي يرفعني في الدنيا قد يكون هو ما يُذلّني يومها."}, {"lbl": "الآيات ٥١ – ٥٩", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ ﴿٥١﴾ فِي جَنَّـٰتٖ وَعُيُونٖ ﴿٥٢﴾ يَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ ﴿٥٣﴾ كَذَٰلِكَ وَزَوَّجۡنَٰهُم بِحُورٍ عِينٖ ﴿٥٤﴾ يَدۡعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ ﴿٥٥﴾ لَا يَذُوقُونَ فِيهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِيمِ ﴿٥٦﴾ فَضۡلٗا مِّن رَّبِّكَۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٥٧﴾ فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ﴿٥٨﴾ فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ ﴿٥٩﴾", "w": [["إن المتقين في مقام أمين", "الذين اتقوا ربهم في الدنيا فآمنوا وعملوا الصالحات بعد اجتناب الشرك والمعاصي في مجلس آمن لا يلحقهم فيه خوف."], ["في جنات وعيون", "هذا هو المقام الأمين."], ["من سندس وإستبرق", "ما رقّ من الديباج وما غلظ منه."], ["متقابلين", "لا ينظر بعضهم إلى قفا بعض لأن الأسرّة تدور بهم."], ["كذلك وزوّجناهم", "الأمر كذلك، وزوّجناهم."], ["بحور عين", "بنساء بيض واسعات الأعين."], ["يدعون فيها بكل فاكهة", "يطلبون من الخدم فيها أن يأتوهم بكل فاكهة."], ["آمنين", "من انقطاعها ومن مضرّاتها ومن كل مخوف."], ["لا يذوقون فيها الموت إلا الموتة الأولى", "لكن الموتة الأولى فقد ذاقوها."], ["فإنما يسّرناه بلسانك", "سهّلنا القرآن بلغتك."], ["لعلهم يتذكرون", "يتعظون فيؤمنون ويوحّدون، لكنهم لا يؤمنون."], ["فارتقب إنهم مرتقبون", "فانتظر هلاكهم فإنهم منتظرون هلاكك."]], "m": "لما ذكر حال أهل النار عقّب بذكر حال أهل الجنة، وهذا أسلوب الترغيب والترهيب الذي تميّز به القرآن لأنه كتاب دعوة وهداية زيادة على أنه كتاب تشريع: إن الذين اتقوه في الدنيا فآمنوا به وأطاعوه ولم يشركوا به في مجلس آمن لا يلحقهم فيه خوف، في بساتين وعيون، يلبسون من الحرير ما رقّ منه وما غلظ، متقابلين على أسرّة تدور بهم، وزوّجناهم بحور عين، والحوراء البيضاء التي في عينيها حَوَر، وهو شدة بياض العين في شدة سوادها، والعيناء الواسعة العينين. يطلبون من الخدم كل فاكهة آمنين من انقطاعها وضررها، لا يذوقون فيها الموت بعد الموتة الأولى التي ذاقوها في الدنيا، فأهلها لا يمرضون ولا يهرمون ولا يموتون، ووقاهم عذاب الجحيم، وهذا دالّ على أن غير المتقين من الموحّدين قد يدخلون النار قبل دخولهم الجنة بخلاف المتقين. فضلاً من ربك، إذ لم يستوجبوه بمجرد تقواهم، وقد قال الرسول ﷺ: «سدّدوا وقاربوا وأبشروا، واعلموا أنه لن يُدخل أحدَكم الجنةَ عملُه»، قالوا: ولا أنت يا رسول الله؟ قال: «ولا أنا إلا أن يتغمّدني الله برحمة منه وفضل». ذلك هو الفوز العظيم: النجاة من النار ودخول الجنة. فإنما سهّلنا القرآن بلغتك العربية لعلهم يتعظون فيؤمنون ويتقون، لكن أكثرهم لم يتعظ، فارتقب ما يحلّ بهم فإنهم منتظرون ما يكون لك من نجاح أو إخفاق.", "h": ["فضل التقوى وكرامة أهلها، والتقوى هي خشية من الله تحمل على طاعة الله بفعل محابّه وترك مكارهه.", "بيان شيء من نعيم أهل الجنة ترغيباً في العمل لها.", "تقرير عقيدة البعث والجزاء.", "بيان الحكمة من تسهيل فهم القرآن الكريم، وهو الاتعاظ المقتضي للتقوى."], "k": "«فضلاً من ربك»… لن يدخلني الجنة عملي وحده؛ فهل أعمل وأنا أرجو فضله لا أتّكل على عملي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (369, 45, 1, 11, 'سورة الجاثية ١ – ١١', 'الجاثية: فبأي حديث بعد الله وآياته يؤمنون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 369) = $j$[{"lbl": "الآيات ١ – ٥", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿٢﴾ إِنَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ﴿٣﴾ وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ﴿٤﴾ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٥﴾", "w": [["حم", "أحد الحروف الهجائية، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب", "القرآن."], ["من الله العزيز الحكيم", "من عند الله العزيز الانتقام من أعدائه، الحكيم في تدبيره."], ["إن في السماوات والأرض", "في خلق السماوات والأرض."], ["لآيات", "لدلالات واضحات على وجود الله وقدرته وعلمه وحكمته، وهي موجبات الربوبية والألوهية له وحده."], ["للمؤمنين", "لأنهم بالإيمان أحياء يبصرون ويسمعون فيرون الآيات."], ["وفي خلقكم", "في خلقكم أيها الناس وتركيب أعضائكم."], ["وما يبثّ من دابة", "ما يخلق وينشر من أنواع الدواب من بهائم وغيرها."], ["آيات لقوم يوقنون", "علامات على قدرة الله على البعث، لا يراها إلا الموقنون في إيمانهم."], ["واختلاف الليل والنهار", "بمجيء هذا وذهاب ذاك، وطول هذا وقصر ذاك."], ["وما أنزل الله من السماء من رزق", "من مطر، وسُمّي رزقاً لأنه سببه."], ["فأحيا به الأرض بعد موتها", "أحيا بالمطر الأرض بعد موت نباتها بالجدب."], ["وتصريف الرياح", "من صبا إلى دبور، ومن شمال إلى جنوب، ومن نسيم إلى عاصفة."], ["آيات لقوم يعقلون", "دلالات واضحة لقوم يستعملون عقولهم في إدراك الأشياء واستنتاج النتائج."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا لهذه الحروف فائدتين في أول غافر والدخان. تنزيل القرآن كان من عند الله العزيز الانتقام من أعدائه، الحكيم في تدبير أمور خلقه. إن في خلق السماوات والأرض وما فيهما من عجائب الصنعة لآيات للمؤمنين تدلّهم على استحقاق ربهم للعبادة دون سواه، وخُصّ المؤمنون لأنهم أحياء يسمعون ويبصرون ويعقلون، فإذا نظروا تجلّى لهم أن خالق هذه العوالم لن يكون إلا قادراً عليماً حكيماً عزيزاً، فلا يُعبد إلا هو. وفي أطوار خلقكم من نطفة إلى علقة إلى مضغة إلى بشر سويّ له سمع وبصر ونطق وفكر، وفيما ينشر في الأرض من أنواع الدواب برّية وبحرية، آيات لقوم يوقنون في إيمانهم كما يوقنون بحقائق الأشياء الثابتة: فالواحد مع الواحد اثنان، والابن لا بد له من أب، فأصحاب هذا اليقين يرون في خلق الإنسان والحيوان آيات على وجود الله وقدرته على البعث الذي أنكره المشركون. وفي تعاقب الليل والنهار وطول أحدهما وقصر الآخر، وما أنزل الله من السماء من مطر هو سبب الرزق فأحيا به الأرض بعد موتها، وتصريف الرياح من صبا إلى دبور ومن رخاء لينة إلى عاصفة، آيات دالة على وجوب عبادة الله وتوحيده، ولكن لذوي العقول النيّرة السليمة، أما الذين لا عقول لهم فلا يرون في هذه ولا في غيرها آية.", "h": ["عظم شأن القرآن الكريم لأنه تنزيل الله العزيز الحكيم.", "الإيمان أعمّ من اليقين ومقدّم عليه في الترتيب، واليقين أعلى في الرتبة.", "فضل العقل السليم إن استُخدم في الخير وما ينفع.", "تقرير ألوهية الله تعالى بتقرير ربوبيته في الخلق والتدبير والعلم والحكمة."], "k": "«وفي خلقكم… آيات لقوم يوقنون»… الآيات حولي وفيّ؛ فهل يزيدني النظر فيها يقيناً؟"}, {"lbl": "الآيات ٦ – ١١", "q": "تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤۡمِنُونَ ﴿٦﴾ وَيۡلٞ لِّكُلِّ أَفَّاكٍ أَثِيمٖ ﴿٧﴾ يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ ﴿٨﴾ وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ﴿٩﴾ مِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ ﴿١٠﴾ هَٰذَا هُدٗىۖ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٌ ﴿١١﴾", "w": [["تلك آيات الله", "تلك الآيات المذكورة حجج الله الدالة على وجوده وقدرته."], ["نتلوها عليك بالحق", "نخبرك عنها بالحق لا بالباطل، كما يُخبر المشركون عن آلهتهم كذباً."], ["فبأي حديث بعد الله وآياته يؤمنون", "فبأي حديث بعد حديث الله هذا وحججه تصدّقون؟ والجواب: لا تؤمنون."], ["ويل لكل أفّاك أثيم", "عذاب الويل لكل كذّاب ذي آثام كبيرة وكثيرة."], ["ثم يُصرّ مستكبراً كأن لم يسمعها", "يُصرّ على الكفر مستكبراً عن الإيمان والتوحيد كأن لم يسمعها."], ["وإذا علم من آياتنا شيئاً", "إذا بلغه شيء من القرآن وعلم أنه منه."], ["اتخذها هزواً", "اتخذها مهزوءاً بها متهكّماً ساخراً منها."], ["لهم عذاب مهين", "ذو إهانة لهم يُهانون به وتُكسر أنوفهم."], ["من ورائهم جهنم", "أمامهم جهنم يوم القيامة، والوراء يُطلق على الأمام."], ["ولا يغني عنهم ما كسبوا شيئاً", "لا يكفي عنهم ما كسبوه من المال والأفعال التي كانوا يعتزّون بها."], ["هذا هدى", "هذا القرآن كله حجج وبراهين ودلالات هادية."], ["لهم عذاب من رجز أليم", "عذاب موجع من نوع الرجز، وهو أشد أنواع العذاب."]], "m": "ما زال السياق في طلب هداية قريش، فبعد أن بيّن تعالى آياته في الآفاق وفي الأنفس قال لرسوله: تلك حجج الله الموجبة لربوبيته وألوهيته نتلوها عليك بالحق، فإن لم يؤمن هؤلاء بالله رباً وإلهاً وبآياته القرآنية الحاملة للهدى والنور فبأي شيء يؤمنون؟ لا شيء. ويل، وعيد شديد، لكل كذّاب يقلب الكذب فيصف الطاهر بالخبيث والصادق بالكاذب، منغمس في كبائر الإثم، يسمع آيات القرآن تُتلى عليه ثم يُصرّ على الكفر مستكبراً عن الإيمان كأن لم يسمعها، فبشّره بعذاب أليم. وإذا بلغه شيء من آيات القرآن أخذ يهزأ بها ويسخر منها، أولئك الأفّاكون الآثمون، وما أكثرهم، لهم عذاب فيه إهانة تنكسر منها أنوفهم التي كانت تأنف الحق. أمامهم جهنم يوم القيامة، ولا يكفي عنهم شيئاً من العذاب ما كسبوا من أموال وأولاد وجاه، ولا ما اتخذوا من دون الله من آلهة، ولهم عذاب عظيم لا يُقدر قدره. هذا القرآن هدى يُخرج من الضلالة إلى الهدى ومن الشرك إلى التوحيد، والذين كفروا به لهم عذاب من أشد أنواع العذاب، لأنهم لم يزكّوا أنفسهم فماتوا على أخبث النفوس.", "h": ["القرآن نور، وأعظم نور، فمن لم يهتدِ عليه لا تُرجى له الهداية أبداً.", "الوعيد الشديد لأهل الإفك والآثام، والإفك الكذب المقلوب.", "شر الناس من إذا سمع آيات الله استهزأ وسخر منها أو ممن يتلوها.", "لم يغنِ عمن مات على الكفر شيء من كسبه في هذه الحياة الدنيا من مال وولد وجاه.", "لم يغنِ عن المشرك ما كان يعبد من دون الله أو مع الله من أصنام وأوثان وملائكة أو أنبياء."], "k": "«ثم يُصرّ مستكبراً كأن لم يسمعها»… كم آية سمعتها اليوم ومضيت كأني لم أسمعها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 369;
insert into public.tdb_cards(topic, i, body) select 369, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿٢﴾ إِنَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ﴿٣﴾ وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ﴿٤﴾ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٥﴾", "w": [["حم", "أحد الحروف الهجائية، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب", "القرآن."], ["من الله العزيز الحكيم", "من عند الله العزيز الانتقام من أعدائه، الحكيم في تدبيره."], ["إن في السماوات والأرض", "في خلق السماوات والأرض."], ["لآيات", "لدلالات واضحات على وجود الله وقدرته وعلمه وحكمته، وهي موجبات الربوبية والألوهية له وحده."], ["للمؤمنين", "لأنهم بالإيمان أحياء يبصرون ويسمعون فيرون الآيات."], ["وفي خلقكم", "في خلقكم أيها الناس وتركيب أعضائكم."], ["وما يبثّ من دابة", "ما يخلق وينشر من أنواع الدواب من بهائم وغيرها."], ["آيات لقوم يوقنون", "علامات على قدرة الله على البعث، لا يراها إلا الموقنون في إيمانهم."], ["واختلاف الليل والنهار", "بمجيء هذا وذهاب ذاك، وطول هذا وقصر ذاك."], ["وما أنزل الله من السماء من رزق", "من مطر، وسُمّي رزقاً لأنه سببه."], ["فأحيا به الأرض بعد موتها", "أحيا بالمطر الأرض بعد موت نباتها بالجدب."], ["وتصريف الرياح", "من صبا إلى دبور، ومن شمال إلى جنوب، ومن نسيم إلى عاصفة."], ["آيات لقوم يعقلون", "دلالات واضحة لقوم يستعملون عقولهم في إدراك الأشياء واستنتاج النتائج."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا لهذه الحروف فائدتين في أول غافر والدخان. تنزيل القرآن كان من عند الله العزيز الانتقام من أعدائه، الحكيم في تدبير أمور خلقه. إن في خلق السماوات والأرض وما فيهما من عجائب الصنعة لآيات للمؤمنين تدلّهم على استحقاق ربهم للعبادة دون سواه، وخُصّ المؤمنون لأنهم أحياء يسمعون ويبصرون ويعقلون، فإذا نظروا تجلّى لهم أن خالق هذه العوالم لن يكون إلا قادراً عليماً حكيماً عزيزاً، فلا يُعبد إلا هو. وفي أطوار خلقكم من نطفة إلى علقة إلى مضغة إلى بشر سويّ له سمع وبصر ونطق وفكر، وفيما ينشر في الأرض من أنواع الدواب برّية وبحرية، آيات لقوم يوقنون في إيمانهم كما يوقنون بحقائق الأشياء الثابتة: فالواحد مع الواحد اثنان، والابن لا بد له من أب، فأصحاب هذا اليقين يرون في خلق الإنسان والحيوان آيات على وجود الله وقدرته على البعث الذي أنكره المشركون. وفي تعاقب الليل والنهار وطول أحدهما وقصر الآخر، وما أنزل الله من السماء من مطر هو سبب الرزق فأحيا به الأرض بعد موتها، وتصريف الرياح من صبا إلى دبور ومن رخاء لينة إلى عاصفة، آيات دالة على وجوب عبادة الله وتوحيده، ولكن لذوي العقول النيّرة السليمة، أما الذين لا عقول لهم فلا يرون في هذه ولا في غيرها آية.", "h": ["عظم شأن القرآن الكريم لأنه تنزيل الله العزيز الحكيم.", "الإيمان أعمّ من اليقين ومقدّم عليه في الترتيب، واليقين أعلى في الرتبة.", "فضل العقل السليم إن استُخدم في الخير وما ينفع.", "تقرير ألوهية الله تعالى بتقرير ربوبيته في الخلق والتدبير والعلم والحكمة."], "k": "«وفي خلقكم… آيات لقوم يوقنون»… الآيات حولي وفيّ؛ فهل يزيدني النظر فيها يقيناً؟"}, {"lbl": "الآيات ٦ – ١١", "q": "تِلۡكَ ءَايَٰتُ ٱللَّهِ نَتۡلُوهَا عَلَيۡكَ بِٱلۡحَقِّۖ فَبِأَيِّ حَدِيثِۭ بَعۡدَ ٱللَّهِ وَءَايَٰتِهِۦ يُؤۡمِنُونَ ﴿٦﴾ وَيۡلٞ لِّكُلِّ أَفَّاكٍ أَثِيمٖ ﴿٧﴾ يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ ﴿٨﴾ وَإِذَا عَلِمَ مِنۡ ءَايَٰتِنَا شَيۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُوْلَـٰٓئِكَ لَهُمۡ عَذَابٞ مُّهِينٞ ﴿٩﴾ مِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ وَلَهُمۡ عَذَابٌ عَظِيمٌ ﴿١٠﴾ هَٰذَا هُدٗىۖ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَهُمۡ عَذَابٞ مِّن رِّجۡزٍ أَلِيمٌ ﴿١١﴾", "w": [["تلك آيات الله", "تلك الآيات المذكورة حجج الله الدالة على وجوده وقدرته."], ["نتلوها عليك بالحق", "نخبرك عنها بالحق لا بالباطل، كما يُخبر المشركون عن آلهتهم كذباً."], ["فبأي حديث بعد الله وآياته يؤمنون", "فبأي حديث بعد حديث الله هذا وحججه تصدّقون؟ والجواب: لا تؤمنون."], ["ويل لكل أفّاك أثيم", "عذاب الويل لكل كذّاب ذي آثام كبيرة وكثيرة."], ["ثم يُصرّ مستكبراً كأن لم يسمعها", "يُصرّ على الكفر مستكبراً عن الإيمان والتوحيد كأن لم يسمعها."], ["وإذا علم من آياتنا شيئاً", "إذا بلغه شيء من القرآن وعلم أنه منه."], ["اتخذها هزواً", "اتخذها مهزوءاً بها متهكّماً ساخراً منها."], ["لهم عذاب مهين", "ذو إهانة لهم يُهانون به وتُكسر أنوفهم."], ["من ورائهم جهنم", "أمامهم جهنم يوم القيامة، والوراء يُطلق على الأمام."], ["ولا يغني عنهم ما كسبوا شيئاً", "لا يكفي عنهم ما كسبوه من المال والأفعال التي كانوا يعتزّون بها."], ["هذا هدى", "هذا القرآن كله حجج وبراهين ودلالات هادية."], ["لهم عذاب من رجز أليم", "عذاب موجع من نوع الرجز، وهو أشد أنواع العذاب."]], "m": "ما زال السياق في طلب هداية قريش، فبعد أن بيّن تعالى آياته في الآفاق وفي الأنفس قال لرسوله: تلك حجج الله الموجبة لربوبيته وألوهيته نتلوها عليك بالحق، فإن لم يؤمن هؤلاء بالله رباً وإلهاً وبآياته القرآنية الحاملة للهدى والنور فبأي شيء يؤمنون؟ لا شيء. ويل، وعيد شديد، لكل كذّاب يقلب الكذب فيصف الطاهر بالخبيث والصادق بالكاذب، منغمس في كبائر الإثم، يسمع آيات القرآن تُتلى عليه ثم يُصرّ على الكفر مستكبراً عن الإيمان كأن لم يسمعها، فبشّره بعذاب أليم. وإذا بلغه شيء من آيات القرآن أخذ يهزأ بها ويسخر منها، أولئك الأفّاكون الآثمون، وما أكثرهم، لهم عذاب فيه إهانة تنكسر منها أنوفهم التي كانت تأنف الحق. أمامهم جهنم يوم القيامة، ولا يكفي عنهم شيئاً من العذاب ما كسبوا من أموال وأولاد وجاه، ولا ما اتخذوا من دون الله من آلهة، ولهم عذاب عظيم لا يُقدر قدره. هذا القرآن هدى يُخرج من الضلالة إلى الهدى ومن الشرك إلى التوحيد، والذين كفروا به لهم عذاب من أشد أنواع العذاب، لأنهم لم يزكّوا أنفسهم فماتوا على أخبث النفوس.", "h": ["القرآن نور، وأعظم نور، فمن لم يهتدِ عليه لا تُرجى له الهداية أبداً.", "الوعيد الشديد لأهل الإفك والآثام، والإفك الكذب المقلوب.", "شر الناس من إذا سمع آيات الله استهزأ وسخر منها أو ممن يتلوها.", "لم يغنِ عمن مات على الكفر شيء من كسبه في هذه الحياة الدنيا من مال وولد وجاه.", "لم يغنِ عن المشرك ما كان يعبد من دون الله أو مع الله من أصنام وأوثان وملائكة أو أنبياء."], "k": "«ثم يُصرّ مستكبراً كأن لم يسمعها»… كم آية سمعتها اليوم ومضيت كأني لم أسمعها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (370, 45, 12, 20, 'سورة الجاثية ١٢ – ٢٠', 'الجاثية: ثم جعلناك على شريعة من الأمر فاتبعها', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 370) = $j$[{"lbl": "الآيات ١٢ – ١٥", "q": "۞ٱللَّهُ ٱلَّذِي سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِيَ ٱلۡفُلۡكُ فِيهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢﴾ وَسَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ جَمِيعٗا مِّنۡهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿١٣﴾ قُل لِّلَّذِينَ ءَامَنُواْ يَغۡفِرُواْ لِلَّذِينَ لَا يَرۡجُونَ أَيَّامَ ٱللَّهِ لِيَجۡزِيَ قَوۡمَۢا بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٤﴾ مَنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ﴿١٥﴾", "w": [["الله الذي سخّر لكم البحر", "الله المعبود بحق لا الآلهة الباطلة سخّر لأجلكم البحر، جعله أملس تطفو فوقه الأخشاب ونحوها."], ["لتجري الفلك فيه بأمره", "لتجري السفن فيه بإذن الله."], ["ولتبتغوا من فضله", "لتسافروا لطلب الرزق من إقليم إلى إقليم."], ["ولعلكم تشكرون", "رجاء أن تشكروا نعم الله عليكم."], ["وسخّر لكم ما في السماوات", "من شمس وقمر ونجوم ورياح وماء أمطار."], ["وما في الأرض جميعاً منه", "ما في الأرض من جبال وأنهار وأشجار ومعادن منه تعالى."], ["لقوم يتفكرون", "يستخدمون عقولهم فيتفكرون في هذه المخلوقات ومن أوجدها ولماذا، فيؤمنوا ويوحّدوا."], ["قل للذين آمنوا يغفروا", "قل يا رسولنا للمؤمنين: يتجاوزوا."], ["للذين لا يرجون أيام الله", "لا يتوقّعون أيام الله بالإدالة منهم للمؤمنين فيذلّهم الله ويُنصر المؤمنون، وهذا قبل الأمر بالجهاد."], ["ليجزي قوماً بما كانوا يكسبون", "ليجزي يوم القيامة من علم أنهم لا يؤمنون بما كسبوه من أذى الرسول والمؤمنين."], ["من عمل صالحاً فلنفسه", "فهو الذي يُرحم ويسعد به."], ["ومن أساء فعليها", "العقوبة تحلّ به لا بغيره."], ["ثم إلى ربكم ترجعون", "بعد الموت، فيحكم بينكم فيما كان بينكم من خلاف."]], "m": "ما زال السياق في هداية قوم النبي ﷺ، يذكّرهم بأن ما بهم من نعم هي من الله لا من الآلهة الباطلة: الله لا غيره هو الذي سخّر لكم البحر لتجري فيه السفن بإذنه ولتطلبوا الرزق بالتجارة، ولعلكم تشكرون، وذلّل لكم ما في السماوات من شمس وقمر ونجوم وسحب وأمطار ورياح، وما في الأرض من جبال وأشجار وأنهار ومعادن وحيوانات، كل ذلك منه وهبه لكم، إن في ذلك لآيات لقوم يتفكرون، فيهديهم تفكيرهم إلى وجوب حمد الله وشكره بعد أن آمنوا به ووحّدوه. ويأمر رسوله أن يقول لصحابته أيام الخوف في مكة قبل الهجرة: اصفحوا عمن يؤذيكم من كفار قريش ولا تردّوا الأذى بمثله، وقد نُسخ هذا بالأمر بالجهاد، ليؤخّر الله جزاءهم إلى يوم القيامة فيجزيهم بأسوأ الجزاء، لأن أذى النبي والمؤمنين أولياء الله من شر المكاسب، وفي قوله «قوماً» ما يدل على أن بعضهم سيؤمن فلا يُعذّب. من عمل صالحاً من إيمان وطاعة فزكت نفسه فعمله عائد عليه، والله غني عن عمل عباده، ومن أساء فلم يؤمن ولم يعمل صالحاً فجزاء كسبه السيئ عائد على نفسه، ثم إلى ربكم ترجعون يوم القيامة فيجزي كلاً بحسب عمله.", "h": ["تقرير التوحيد والبعث والجزاء والنبوة.", "بيان علة الإنعام الإلهي على العبد، وهي أن يشكر الله تعالى بحمده والثناء عليه وصرف تلك النعم في مرضاته تعالى لا في معاصيه الموجبة لسخطه.", "مشروعية التسامح مع الكفار والتجاوز عن أذاهم في حال ضعف المسلمين.", "تقرير قاعدة أن المرء لا يؤخذ بجريرة غيره.", "تقرير أن الكسب يؤثّر في النفس ويكون صفة لها، وبه يتم الجزاء في الدار الآخرة من خير وغيره، قال تعالى: «سيجزيهم وصفهم إنه حكيم عليم»."], "k": "«وسخّر لكم ما في السماوات وما في الأرض جميعاً منه»… كل ما يخدمني اليوم من نعمته؛ فهل أصرفه فيما يرضيه؟"}, {"lbl": "الآيات ١٦ – ٢٠", "q": "وَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ﴿١٦﴾ وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿١٧﴾ ثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٖ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿١٨﴾ إِنَّهُمۡ لَن يُغۡنُواْ عَنكَ مِنَ ٱللَّهِ شَيۡـٔٗاۚ وَإِنَّ ٱلظَّـٰلِمِينَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۖ وَٱللَّهُ وَلِيُّ ٱلۡمُتَّقِينَ ﴿١٩﴾ هَٰذَا بَصَـٰٓئِرُ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُوقِنُونَ ﴿٢٠﴾", "w": [["الكتاب", "التوراة، لأنها الحاوية للأحكام الشرعية بخلاف الزبور."], ["والحكم", "الفصل في القضايا بين المتنازعين على وجه يحقق العدل."], ["والنبوة ورزقناهم من الطيبات", "جعلنا فيهم النبوة كموسى وهارون وداود وسليمان، ورزقناهم من الطيبات كالمنّ والسلوى."], ["وفضّلناهم على العالمين", "على عالمي زمانهم من الأمم المعاصرة لهم."], ["إلا من بعد ما جاءهم العلم بغياً بينهم", "لم يختلفوا إلا من بعد ما جاءهم العلم ببعثة النبي محمد ﷺ، حسداً للعرب أولاد إسماعيل أن تكون النبوة فيهم."], ["ثم جعلناك على شريعة من الأمر", "جعلناك يا رسولنا على شريعة من أمر الدين الحق الذي ارتضاه الله لعباده."], ["فاتبعها", "الزم الأخذ بها والسير على طريقها فإنها تفضي بك إلى سعادة الدارين."], ["ولا تتبع أهواء الذين لا يعلمون", "من مشركي العرب ومن ضلال أهل الكتاب."], ["إنهم لن يغنوا عنك من الله شيئاً", "إن اتبعت ما يقترحون عليك مما يوافق أهواءهم لن يدفعوا عنك من العذاب شيئاً."], ["وإن الظالمين بعضهم أولياء بعض", "ينصر بعضهم بعضاً في الدنيا، أما في الآخرة فلا."], ["والله ولي المتقين", "متولّيهم في أمورهم كلها وناصرهم على أعدائهم."], ["هذا بصائر للناس", "هذا القرآن أنوار هداية يهتدون به إلى ما يكمّلهم ويسعدهم."], ["وهدى ورحمة لقوم يوقنون", "لأهل اليقين في إيمانهم، فهم الذين يهتدون به ويُرحمون عليه."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ، فعرض عليهم حالاً شبيهة بحالهم: ولقد آتينا بني إسرائيل، أولاد يعقوب الملقّب بإسرائيل، التوراة والفقه بأحكام الشرع، وجعلنا منهم أنبياء ورسلاً كموسى وهارون ويوسف وداود وسليمان وعيسى، ورزقناهم من الطيبات، وفضّلناهم على فرعون وقومه وعلى من جاور بلادهم أيام إيمانهم واستقامتهم، وآتيناهم بيّنات من أمر الدين، فما اختلفوا إلا من بعد ما جاءهم العلم الإلهي يحمله القرآن ونبيه، فاختلفوا فيما كان عندهم من الأنباء عن نبي آخر الزمان ونعوته، فحملهم البغي، وهو الحسد، على الكفر به؛ ونظيرها آية البقرة: فلما جاءهم ما عرفوا كفروا به. إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون، وهذه تسلية للرسول ﷺ. ثم جعلناك على شريعة من أمر ديننا الإسلام الذي هو دين الأنبياء من قبلك، فاتبعها ولا تحِد عنها متبعاً أهواء زعماء قريش الذين يقدّمون لك اقتراحاتهم، ولا أهواء ضلال أهل الكتاب، إنهم جهّال لا يعلمون سبيل النجاة ولا سبيل العزة في الدنيا. إن اتبعت أهواءهم لن يدفعوا عنك من العذاب شيئاً، وإن الظالمين يتعاونون على الباطل في الدنيا، والله ولي المتقين في الدنيا والآخرة، فعليك بولاية الله ودع ولاية أعدائه. هذا القرآن عيون القلوب، بها تبصر النافع من الضار والحق من الباطل، وهدى ورحمة لقوم يوقنون فعملوا به عقائد وعبادات وأحكاماً وآداباً وأخلاقاً، كما حصل للسلف الصالح، وقد كان خلق النبي ﷺ القرآن كما قالت عائشة رضي الله عنها.", "h": ["بيان أن كفر أهل الكتاب كان حسداً للنبي ﷺ وقومه من العرب.", "بيان إفضال الله تعالى على بني إسرائيل حيث أعطاهم الكتاب والحكم والنبوة، ومع هذا اختلفوا في الحق حسداً وطمعاً في الرئاسة.", "تقرير البعث والجزاء والنبوة والتوحيد.", "وجوب لزوم تطبيق الشريعة الإسلامية وعدم التنازل عن شيء منها.", "تقرير ولاية الله تعالى لأهل الإيمان به وتقواه بفعل محابّه وترك مساخطه.", "القرآن كتاب هداية وإصلاح، ولا يتم شيء من هداية الناس وإصلاحهم إلا عليه."], "k": "«هذا بصائر للناس»… القرآن عيون لقلبي؛ فهل أنظر به إلى أموري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 370;
insert into public.tdb_cards(topic, i, body) select 370, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٢ – ١٥", "q": "۞ٱللَّهُ ٱلَّذِي سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِيَ ٱلۡفُلۡكُ فِيهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٢﴾ وَسَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ جَمِيعٗا مِّنۡهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿١٣﴾ قُل لِّلَّذِينَ ءَامَنُواْ يَغۡفِرُواْ لِلَّذِينَ لَا يَرۡجُونَ أَيَّامَ ٱللَّهِ لِيَجۡزِيَ قَوۡمَۢا بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٤﴾ مَنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ﴿١٥﴾", "w": [["الله الذي سخّر لكم البحر", "الله المعبود بحق لا الآلهة الباطلة سخّر لأجلكم البحر، جعله أملس تطفو فوقه الأخشاب ونحوها."], ["لتجري الفلك فيه بأمره", "لتجري السفن فيه بإذن الله."], ["ولتبتغوا من فضله", "لتسافروا لطلب الرزق من إقليم إلى إقليم."], ["ولعلكم تشكرون", "رجاء أن تشكروا نعم الله عليكم."], ["وسخّر لكم ما في السماوات", "من شمس وقمر ونجوم ورياح وماء أمطار."], ["وما في الأرض جميعاً منه", "ما في الأرض من جبال وأنهار وأشجار ومعادن منه تعالى."], ["لقوم يتفكرون", "يستخدمون عقولهم فيتفكرون في هذه المخلوقات ومن أوجدها ولماذا، فيؤمنوا ويوحّدوا."], ["قل للذين آمنوا يغفروا", "قل يا رسولنا للمؤمنين: يتجاوزوا."], ["للذين لا يرجون أيام الله", "لا يتوقّعون أيام الله بالإدالة منهم للمؤمنين فيذلّهم الله ويُنصر المؤمنون، وهذا قبل الأمر بالجهاد."], ["ليجزي قوماً بما كانوا يكسبون", "ليجزي يوم القيامة من علم أنهم لا يؤمنون بما كسبوه من أذى الرسول والمؤمنين."], ["من عمل صالحاً فلنفسه", "فهو الذي يُرحم ويسعد به."], ["ومن أساء فعليها", "العقوبة تحلّ به لا بغيره."], ["ثم إلى ربكم ترجعون", "بعد الموت، فيحكم بينكم فيما كان بينكم من خلاف."]], "m": "ما زال السياق في هداية قوم النبي ﷺ، يذكّرهم بأن ما بهم من نعم هي من الله لا من الآلهة الباطلة: الله لا غيره هو الذي سخّر لكم البحر لتجري فيه السفن بإذنه ولتطلبوا الرزق بالتجارة، ولعلكم تشكرون، وذلّل لكم ما في السماوات من شمس وقمر ونجوم وسحب وأمطار ورياح، وما في الأرض من جبال وأشجار وأنهار ومعادن وحيوانات، كل ذلك منه وهبه لكم، إن في ذلك لآيات لقوم يتفكرون، فيهديهم تفكيرهم إلى وجوب حمد الله وشكره بعد أن آمنوا به ووحّدوه. ويأمر رسوله أن يقول لصحابته أيام الخوف في مكة قبل الهجرة: اصفحوا عمن يؤذيكم من كفار قريش ولا تردّوا الأذى بمثله، وقد نُسخ هذا بالأمر بالجهاد، ليؤخّر الله جزاءهم إلى يوم القيامة فيجزيهم بأسوأ الجزاء، لأن أذى النبي والمؤمنين أولياء الله من شر المكاسب، وفي قوله «قوماً» ما يدل على أن بعضهم سيؤمن فلا يُعذّب. من عمل صالحاً من إيمان وطاعة فزكت نفسه فعمله عائد عليه، والله غني عن عمل عباده، ومن أساء فلم يؤمن ولم يعمل صالحاً فجزاء كسبه السيئ عائد على نفسه، ثم إلى ربكم ترجعون يوم القيامة فيجزي كلاً بحسب عمله.", "h": ["تقرير التوحيد والبعث والجزاء والنبوة.", "بيان علة الإنعام الإلهي على العبد، وهي أن يشكر الله تعالى بحمده والثناء عليه وصرف تلك النعم في مرضاته تعالى لا في معاصيه الموجبة لسخطه.", "مشروعية التسامح مع الكفار والتجاوز عن أذاهم في حال ضعف المسلمين.", "تقرير قاعدة أن المرء لا يؤخذ بجريرة غيره.", "تقرير أن الكسب يؤثّر في النفس ويكون صفة لها، وبه يتم الجزاء في الدار الآخرة من خير وغيره، قال تعالى: «سيجزيهم وصفهم إنه حكيم عليم»."], "k": "«وسخّر لكم ما في السماوات وما في الأرض جميعاً منه»… كل ما يخدمني اليوم من نعمته؛ فهل أصرفه فيما يرضيه؟"}, {"lbl": "الآيات ١٦ – ٢٠", "q": "وَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ﴿١٦﴾ وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿١٧﴾ ثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٖ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡوَآءَ ٱلَّذِينَ لَا يَعۡلَمُونَ ﴿١٨﴾ إِنَّهُمۡ لَن يُغۡنُواْ عَنكَ مِنَ ٱللَّهِ شَيۡـٔٗاۚ وَإِنَّ ٱلظَّـٰلِمِينَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۖ وَٱللَّهُ وَلِيُّ ٱلۡمُتَّقِينَ ﴿١٩﴾ هَٰذَا بَصَـٰٓئِرُ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُوقِنُونَ ﴿٢٠﴾", "w": [["الكتاب", "التوراة، لأنها الحاوية للأحكام الشرعية بخلاف الزبور."], ["والحكم", "الفصل في القضايا بين المتنازعين على وجه يحقق العدل."], ["والنبوة ورزقناهم من الطيبات", "جعلنا فيهم النبوة كموسى وهارون وداود وسليمان، ورزقناهم من الطيبات كالمنّ والسلوى."], ["وفضّلناهم على العالمين", "على عالمي زمانهم من الأمم المعاصرة لهم."], ["إلا من بعد ما جاءهم العلم بغياً بينهم", "لم يختلفوا إلا من بعد ما جاءهم العلم ببعثة النبي محمد ﷺ، حسداً للعرب أولاد إسماعيل أن تكون النبوة فيهم."], ["ثم جعلناك على شريعة من الأمر", "جعلناك يا رسولنا على شريعة من أمر الدين الحق الذي ارتضاه الله لعباده."], ["فاتبعها", "الزم الأخذ بها والسير على طريقها فإنها تفضي بك إلى سعادة الدارين."], ["ولا تتبع أهواء الذين لا يعلمون", "من مشركي العرب ومن ضلال أهل الكتاب."], ["إنهم لن يغنوا عنك من الله شيئاً", "إن اتبعت ما يقترحون عليك مما يوافق أهواءهم لن يدفعوا عنك من العذاب شيئاً."], ["وإن الظالمين بعضهم أولياء بعض", "ينصر بعضهم بعضاً في الدنيا، أما في الآخرة فلا."], ["والله ولي المتقين", "متولّيهم في أمورهم كلها وناصرهم على أعدائهم."], ["هذا بصائر للناس", "هذا القرآن أنوار هداية يهتدون به إلى ما يكمّلهم ويسعدهم."], ["وهدى ورحمة لقوم يوقنون", "لأهل اليقين في إيمانهم، فهم الذين يهتدون به ويُرحمون عليه."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ، فعرض عليهم حالاً شبيهة بحالهم: ولقد آتينا بني إسرائيل، أولاد يعقوب الملقّب بإسرائيل، التوراة والفقه بأحكام الشرع، وجعلنا منهم أنبياء ورسلاً كموسى وهارون ويوسف وداود وسليمان وعيسى، ورزقناهم من الطيبات، وفضّلناهم على فرعون وقومه وعلى من جاور بلادهم أيام إيمانهم واستقامتهم، وآتيناهم بيّنات من أمر الدين، فما اختلفوا إلا من بعد ما جاءهم العلم الإلهي يحمله القرآن ونبيه، فاختلفوا فيما كان عندهم من الأنباء عن نبي آخر الزمان ونعوته، فحملهم البغي، وهو الحسد، على الكفر به؛ ونظيرها آية البقرة: فلما جاءهم ما عرفوا كفروا به. إن ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون، وهذه تسلية للرسول ﷺ. ثم جعلناك على شريعة من أمر ديننا الإسلام الذي هو دين الأنبياء من قبلك، فاتبعها ولا تحِد عنها متبعاً أهواء زعماء قريش الذين يقدّمون لك اقتراحاتهم، ولا أهواء ضلال أهل الكتاب، إنهم جهّال لا يعلمون سبيل النجاة ولا سبيل العزة في الدنيا. إن اتبعت أهواءهم لن يدفعوا عنك من العذاب شيئاً، وإن الظالمين يتعاونون على الباطل في الدنيا، والله ولي المتقين في الدنيا والآخرة، فعليك بولاية الله ودع ولاية أعدائه. هذا القرآن عيون القلوب، بها تبصر النافع من الضار والحق من الباطل، وهدى ورحمة لقوم يوقنون فعملوا به عقائد وعبادات وأحكاماً وآداباً وأخلاقاً، كما حصل للسلف الصالح، وقد كان خلق النبي ﷺ القرآن كما قالت عائشة رضي الله عنها.", "h": ["بيان أن كفر أهل الكتاب كان حسداً للنبي ﷺ وقومه من العرب.", "بيان إفضال الله تعالى على بني إسرائيل حيث أعطاهم الكتاب والحكم والنبوة، ومع هذا اختلفوا في الحق حسداً وطمعاً في الرئاسة.", "تقرير البعث والجزاء والنبوة والتوحيد.", "وجوب لزوم تطبيق الشريعة الإسلامية وعدم التنازل عن شيء منها.", "تقرير ولاية الله تعالى لأهل الإيمان به وتقواه بفعل محابّه وترك مساخطه.", "القرآن كتاب هداية وإصلاح، ولا يتم شيء من هداية الناس وإصلاحهم إلا عليه."], "k": "«هذا بصائر للناس»… القرآن عيون لقلبي؛ فهل أنظر به إلى أموري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (371, 45, 21, 37, 'سورة الجاثية ٢١ – ٣٧', 'الجاثية: وترى كل أمة جاثية', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 371) = $j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "أَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ مَا يَحۡكُمُونَ ﴿٢١﴾ وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٢﴾ أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ﴿٢٣﴾", "w": [["اجترحوا السيئات", "اكتسبوا بجوارحهم الشرك والمعاصي."], ["سواءً محياهم ومماتهم", "محياهم ومماتهم سواء؟ لا، المؤمنون في الجنة والمشركون في النار."], ["ساء ما يحكمون", "ساء حكماً حكمهم بالتساوي مع المؤمنين."], ["ولتُجزى كل نفس بما كسبت", "ليجزي الله كل نفس ما كسبت من خير وشر."], ["أفرأيت من اتخذ إلهه هواه", "أخبرني عمن جعل معبوده هواه."], ["وأضلّه الله على علم", "على علم من الله تعالى بأنه أهل للإضلال وعدم الهداية."], ["وجعل على بصره غشاوة", "ظلمة على عينيه فلا يبصر الآيات والدلائل."], ["أفلا تذكّرون", "أفلا تتذكّرون أيها الناس فتتعظون؟"]], "m": "لما ذكر الظالمين والمتقين وجزاء كل منهم ذكر هنا ما يقرّر اختلاف جزائهم: أم حسب الذين اكتسبوا بجوارحهم الشرك والمعاصي أن نجعلهم كالذين آمنوا بالله رباً وإلهاً وعملوا الصالحات من إقام الصلاة وإيتاء الزكاة وصيام رمضان والجهاد والحج والأمر بالمعروف والنهي عن المنكر، سواءً محياهم ومماتهم؟ ساء حكماً حكمهم هذا؛ أنكر تعالى على من يظن أن الكافر يعيش على المعاصي والمؤمن على الطاعة ثم يموتون ولا يُجزى أحد منهما، وأسوأ منه ظن بعضهم أنهم إذا ماتوا يُكرمون بخير ما يُكرم به المؤمنون، وهذا غرور عجيب، فحكم أنه لا يسوّي بين برّ وفاجر، لأن ذلك منافٍ للعدل، والله خلق السماوات والأرض بالحق، وأنزل الشرائع وأرسل الرسل ليعمل الناس، ولتُجزى كل نفس بما كسبت وهم لا يُظلمون. أفرأيت من جعل معبوده ما تهواه نفسه، فما هويت قولاً إلا قاله ولا عملاً إلا عمله ولا اعتقاداً إلا اعتقده، ضارباً بالعقل والشرع عرض الحائط؟ وأضلّه الله على علم منه سبق بأن هذا الإنسان لا يهتدي ولو جاءته كل آية، وختم على سمعه حسب سنته فأصبح لا يسمع الحق كأنه أصم، وعلى قلبه فلا يعقل معاني ما يسمع، وجعل على بصره ظلمة فلا يرى الأدلة الهادية، فمن يهديه من بعد الله؟ لا أحد؛ وسنة الله في الإضلال أن يُدعى العبد إلى الحق فيتكبّر ويسخر ويحارب فترة يصبح بعدها غير قابل للهداية. أفلا تتذكّرون أيها الناس فتؤمنوا وتوحّدوا وتعملوا الصالحات فتسعدوا في الدارين؟", "h": ["بطلان اعتقاد الكافرين في أن الناس يحيون ويموتون بلا جزاء على الكسب.", "تقرير البعث والجزاء.", "موعظة كبيرة في هذه الآية: «أم حسب الذين اجترحوا السيئات…» إلى آخرها، حتى إن أحد رجال السلف الصالح قام يتهجّد من الليل فقرأ حتى انتهى إلى هذه الآية، فأخذ يردّدها ويبكي.", "التنديد بالهوى والتحذير من اتباعه، فقد يُفضي بالعبد إلى ترك متابعة الهدى إلى مطاوعة الهوى، فيصبح معبوده هواه لا الرب تعالى مولاه.", "التحذير من ارتكاب سنن الضلال المفضي بالعبد إلى الضلال الذي لا هداية معه."], "k": "«أفرأيت من اتخذ إلهه هواه»… في أي أمر أطيع هواي وأترك ما أعرف أنه الحق؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "وَقَالُواْ مَا هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا يُهۡلِكُنَآ إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَظُنُّونَ ﴿٢٤﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٥﴾ قُلِ ٱللَّهُ يُحۡيِيكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يَجۡمَعُكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢٦﴾", "w": [["وقالوا ما هي إلا حياتنا الدنيا", "قال منكرو البعث: ما الحياة إلا هذه، وليس وراءها حياة."], ["نموت ونحيا", "يموت بعضنا ويحيا بعضنا بأن يولدوا فيحيوا ويموتوا."], ["وما يهلكنا إلا الدهر", "وما يميتنا إلا مرور الزمان علينا."], ["وما لهم بذلك من علم", "ليس لهم أدنى علم على قولهم، لا من وحي وكتاب إلهي ولا من عقل."], ["إن هم إلا يظنون", "ما هم إلا يظنون فقط، والظن لا قيمة له ولا يُبنى عليه حكم."], ["وإذا تتلى عليهم آياتنا بيّنات", "إذا قُرئت عليهم الآيات الدالة على البعث والجزاء."], ["ما كان حجتهم", "لم تكن لهم من حجة إلا قولهم."], ["إلا أن قالوا ائتوا بآبائنا", "أحيوا لنا آباءنا الذين ماتوا وأتوا بهم إلينا."], ["قل الله يحييكم ثم يميتكم", "قل يا رسولنا: الله الذي أحياكم حين كنتم نطفاً ميتة ثم يميتكم."], ["ثم يجمعكم إلى يوم القيامة", "ثم بعد الموت يجمعكم إلى يوم القيامة للحساب والجزاء."], ["لا ريب فيه", "لا شك في مجيئه في وقته المحدد له."], ["ولكن أكثر الناس لا يعلمون", "لعدم تلقّيهم العلم عن الوحي الإلهي لكفرهم بالرسل والكتب."]], "m": "بعد بيان اعتقاد بعض المشركين في استواء حال المؤمنين والكافرين، حكى قول منكري البعث بالكلية ليردّ عليهم: وقالوا ما هناك إلا حياتنا هذه، نموت نحن الأحياء ويحيا أبناؤنا من بعدنا وهكذا تستمر الحياة، وما يفنينا إلا مرور الزمان؛ وهو إلحاد كامل وإنكار للخالق، وتناقض منهم، إذ إذا سُئلوا من خلقهم قالوا: الله، فينسبون إليه الخلق وهو أصعب، ولا ينسبون إليه الإماتة وهي أهون. فردّ تعالى مذهبهم الدهري: ما لهم بذلك من علم نقلي عن وحي، ولا عقلي عن عقل سليم لا يُنقض حكمه، إن هم إلا يظنون ويخرصون، وقضايا العقيدة لا تكون بالظن، والظن أكذب الحديث. وإذا قرأ عليهم رسول الله ﷺ آيات القرآن الدالة على البعث ما كانت لهم حجة يردّون بها إلا قولهم: أحيوا لنا آباءنا الذين ماتوا إن كنتم صادقين. فقال تعالى: قل لهم: الله يحييكم إذ كنتم نطفاً ميتة، ثم يميتكم بدون اختياركم، فالقادر على الإحياء والإماتة لا يُحيل العقل أن يحيي من أماتهم، وإنما لم يحيهم اليوم كما طلبتم لأنه لا فائدة منه، ولأنه يتنافى مع الحكمة العالية في خلق الحياتين، إذ خُلقوا ليعملوا ثم يُجازوا، ولهذا قال: ثم يجمعكم أحياء إلى يوم القيامة لا شك في مجيئه، ولكن أكثر الناس لا يعلمون، لأنهم لا يتفكّرون، ولأنهم بتكذيبهم بالوحي سدّوا في وجوههم طريق العلم الصحيح.", "h": ["تقرير البعث والجزاء.", "الرد على الدهريين، وهم الذين ينسبون الحياة والموت للدهر وينفون وجود الخالق عز وجل.", "بيان أن الكفار لا دليل لهم عقلي ولا نقلي على صحة الكفر، عقيدة كان أو عملاً.", "عدم إحياء الله تعالى لمن مات حين طالب به المكذّبون حتى يؤمنوا لم يكن عن عجز، بل لأنه يتنافى مع الحكمة التي دار عليها الكون كله.", "بيان أن أكثر الناس لا يعلمون، وذلك لأنهم كذّبوا بالوحي الإلهي في الكتاب والسنة.", "بيان أنه لا علم صحيح إلا من طريق الوحي الإلهي."], "k": "«وما يهلكنا إلا الدهر»… الأيام لا تفني، بل تقرّبني من لقاء ربي؛ فكيف أحسب أيامي؟"}, {"lbl": "الآيات ٢٧ – ٣٢", "q": "وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَخۡسَرُ ٱلۡمُبۡطِلُونَ ﴿٢٧﴾ وَتَرَىٰ كُلَّ أُمَّةٖ جَاثِيَةٗۚ كُلُّ أُمَّةٖ تُدۡعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلۡيَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٨﴾ هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٩﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ﴿٣٠﴾ وَأَمَّا ٱلَّذِينَ كَفَرُوٓاْ أَفَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمٗا مُّجۡرِمِينَ ﴿٣١﴾ وَإِذَا قِيلَ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱلسَّاعَةُ لَا رَيۡبَ فِيهَا قُلۡتُم مَّا نَدۡرِي مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنّٗا وَمَا نَحۡنُ بِمُسۡتَيۡقِنِينَ ﴿٣٢﴾", "w": [["ولله ملك السماوات والأرض", "خلقاً وملكاً وتصرفاً، يفعل ما يشاء ويحكم ما يريد."], ["يخسر المبطلون", "يوم تقوم الساعة يخسر أصحاب الباطل بصيرورتهم إلى النار."], ["وترى كل أمة جاثية", "كل أمة ذات دين جاثية على ركبها تنتظر حكم الله فيها."], ["كل أمة تُدعى إلى كتابها", "إلى كتاب أعمالها، فإن كان خيراً فخير وإن كان شراً فشر."], ["اليوم تُجزون ما كنتم تعملون", "يقال لهم: اليوم تُجزون ما كنتم تعملون في الدنيا من خير وشر."], ["هذا كتابنا ينطق عليكم بالحق", "ديوان الحفظة الذي دوّنوا فيه أعمالكم شاهد عليكم بالحق."], ["إنا كنا نستنسخ ما كنتم تعملون", "نأمر بنسخ ما كنتم تعملون."], ["فيدخلهم ربهم في رحمته", "في جنته."], ["ذلك هو الفوز المبين", "الفوز البيّن الظاهر، وهو النجاة من النار ودخول الجنة."], ["أفلم تكن آياتي تتلى عليكم", "يقال لهم: ألم تأتكم رسلي فلم تكن آياتي تتلى عليكم؟"], ["فاستكبرتم وكنتم قوماً مجرمين", "عن آيات الله فلم تؤمنوا بها، وكنتم بذلك قوماً كافرين."], ["إن وعد الله حق", "بالبعث والجزاء العادل يوم القيامة حق ثابت."], ["إن نظن إلا ظناً وما نحن بمستيقنين", "ما كنا مستيقنين بالبعث، وإنما كنا نظنه ولا نجزم به."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: ولله ملك السماوات والأرض خلقاً وملكاً وتصرفاً، ومن كان هذا وصفه من القدرة والعلم لا يُنكر عليه بعث العباد بعد موتهم. ويوم تقوم الساعة يخسر المبطلون كل شيء حتى أنفسهم، يخسرون منازلهم في الجنة يرثها عنهم المؤمنون، ويرثون منازل المؤمنين في النار، ذلك هو الخسران المبين. وترى أيها الرسول يوم القيامة كل أهل دين وملة قد جثوا على ركبهم خوفاً وذلاً، كل أمة تُدعى إلى كتابها، ويقال لهم: اليوم تُجزون ما كنتم تعملون في الدنيا، فإذا حاولوا الإنكار قيل لهم: هذا كتاب الأعمال الذي دوّنته الحفظة ينطق عليكم بالحق، إنا كنا نأمر ملائكتنا بإثبات أعمالكم وحفظها، وها هي بين أيديكم. فأما الذين آمنوا وعملوا الصالحات وتركوا الشرك والمعاصي فيدخلهم ربهم في رحمته وهي الجنة، ذلك هو الفوز المبين، إذ الفوز النجاة من المرهوب والظفر بالمحبوب. وأما الذين كفروا فيقال لهم: ألم تأتكم رسلي فكانت آياتي تُتلى عليكم فاستكبرتم عنها، وكنتم باستكباركم قوماً مجرمين على أنفسكم؟ وإذا قيل لكم: إن وعد الله بالبعث حق والساعة آتية لا ريب فيها، قلتم متجاهلين متعجّبين: ما ندري ما الساعة، إن نظن إلا ظناً وما نحن بمستيقنين؛ وهذا حال كثير من الناس الذين يؤمنون بالله وبلقائه وهم لا يفترون عن المعاصي ولا يقصّرون عن فعل الشر.", "h": ["تقرير عقيدة البعث والجزاء بذكر بعض ما يقع يوم القيامة.", "تقرير عقيدة كتابة أعمال العباد وتقديمها لهم يوم القيامة في كتاب خاص.", "تقرير أن الإيمان والعمل الصالح سبب الفوز، وأن الشرك والمعاصي سبب الخسران.", "الظن في العقائد كالكفر بها، والعياذ بالله تعالى."], "k": "«هذا كتابنا ينطق عليكم بالحق»… لو قُرئ عليّ كتاب يومي هذا، ماذا كنت سأسمع؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٣﴾ وَقِيلَ ٱلۡيَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ ﴿٣٤﴾ ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَايَٰتِ ٱللَّهِ هُزُوٗا وَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٣٥﴾ فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٣٦﴾ وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣٧﴾", "w": [["وبدا لهم سيئات ما عملوا", "ظهر لهم يوم القيامة جزاء سيئات ما عملوه في الدنيا من الشرك والمعاصي."], ["وحاق بهم ما كانوا به يستهزئون", "نزل وأحاط بهم العذاب الذي كانوا يستهزئون به إذا خُوّفوا منه."], ["وقيل اليوم ننساكم", "قال الله تعالى لهم: اليوم نترككم في النار."], ["كما نسيتم لقاء يومكم هذا", "مثل ما نسيتم يومكم هذا فلم تعملوا له بما ينجي فيه."], ["ومأواكم النار", "محل إقامتكم النار."], ["وما لكم من ناصرين", "ينصرونكم بإخراجكم من النار."], ["ذلكم بأنكم اتخذتم آيات الله هزواً", "ذلكم العذاب بسبب كفركم واتخاذكم آيات الله شيئاً مهزوءاً به."], ["وغرّتكم الحياة الدنيا", "طول العمر والتمتع بالشهوات والمستلذّات."], ["ولا هم يُستعتبون", "لا يُؤذن لهم في الاستعتاب ليُعتبوا فيتوبوا."], ["فلله الحمد رب السماوات ورب الأرض", "فلله وحده الوصف بالجميل لإنجاز وعيده لأعدائه."], ["وله الكبرياء في السماوات والأرض", "العظمة والحكم النافذ الناجز على من شاء."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبير خلقه."]], "m": "ما زال السياق في عرض مشاهد القيامة لعل السامعين يتعظون: وظهر للمشركين المكذبين بالبعث جزاء سيئات أعمالهم، وشاهدوا العذاب الذي كانوا إذا خُوّفوا منه استهزؤوا به، وقد نزل بساحتهم وأحاط بهم. وقال لهم الرب تعالى: اليوم نترككم في عذاب النار كما تركتم العمل المنجي من هذا العذاب، وهو الإيمان والعمل الصالح، ومأواكم النار وليس لكم من ينصركم فيخلّصكم منها. ذلكم الحكم بسبب اتخاذكم آيات الله الحاملة للحجج على وجوده ووجوب توحيده شيئاً مهزوءاً به، وغرّتكم الحياة الدنيا بزخرفها وطول أعماركم فيها فلم تؤمنوا. فاليوم لا يخرجون منها، وترك مخاطبتهم إشعاراً بأنه لا كرامة لهم، ولا يُطلب منهم أن يُرضوا ربهم بالتوبة، إذ لا توبة بعد الموت والرجوع إلى الدنيا غير ممكن، وهنا تعظم حسرتهم ويشتد كربهم. فلله الحمد رب السماوات ورب الأرض رب العالمين، حمد نفسه وقصر الحمد عليه بعد أن أنجز ما أوعد به الكافرين، وله العظمة والسلطان في السماوات والأرض، وهو العزيز الذي لا يُمانع ولا يُغالب، الحكيم الذي يضع كل شيء في موضعه، ويتجلّى ذلك في إكرام أوليائه برحمتهم وإهانة أعدائهم بتعذيبهم.", "h": ["بيان أن الاستهزاء بآيات الله وشرائعه كفر موجب للعذاب.", "تقرير قاعدة: الجزاء من جنس العمل، وكما يدين الفتى يُدان.", "مشروعية الحمد عند الفراغ من أي عمل صالح أو مباح."], "k": "«اليوم ننساكم كما نسيتم لقاء يومكم هذا»… ما الذي أنساه من لقاء ربي وسط مشاغلي؟"}]$j$::jsonb then 0 else 1 end;
