insert into public.tdb_cards(topic, i, body) select 371, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٣", "q": "أَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ مَا يَحۡكُمُونَ ﴿٢١﴾ وَخَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿٢٢﴾ أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ﴿٢٣﴾", "w": [["اجترحوا السيئات", "اكتسبوا بجوارحهم الشرك والمعاصي."], ["سواءً محياهم ومماتهم", "محياهم ومماتهم سواء؟ لا، المؤمنون في الجنة والمشركون في النار."], ["ساء ما يحكمون", "ساء حكماً حكمهم بالتساوي مع المؤمنين."], ["ولتُجزى كل نفس بما كسبت", "ليجزي الله كل نفس ما كسبت من خير وشر."], ["أفرأيت من اتخذ إلهه هواه", "أخبرني عمن جعل معبوده هواه."], ["وأضلّه الله على علم", "على علم من الله تعالى بأنه أهل للإضلال وعدم الهداية."], ["وجعل على بصره غشاوة", "ظلمة على عينيه فلا يبصر الآيات والدلائل."], ["أفلا تذكّرون", "أفلا تتذكّرون أيها الناس فتتعظون؟"]], "m": "لما ذكر الظالمين والمتقين وجزاء كل منهم ذكر هنا ما يقرّر اختلاف جزائهم: أم حسب الذين اكتسبوا بجوارحهم الشرك والمعاصي أن نجعلهم كالذين آمنوا بالله رباً وإلهاً وعملوا الصالحات من إقام الصلاة وإيتاء الزكاة وصيام رمضان والجهاد والحج والأمر بالمعروف والنهي عن المنكر، سواءً محياهم ومماتهم؟ ساء حكماً حكمهم هذا؛ أنكر تعالى على من يظن أن الكافر يعيش على المعاصي والمؤمن على الطاعة ثم يموتون ولا يُجزى أحد منهما، وأسوأ منه ظن بعضهم أنهم إذا ماتوا يُكرمون بخير ما يُكرم به المؤمنون، وهذا غرور عجيب، فحكم أنه لا يسوّي بين برّ وفاجر، لأن ذلك منافٍ للعدل، والله خلق السماوات والأرض بالحق، وأنزل الشرائع وأرسل الرسل ليعمل الناس، ولتُجزى كل نفس بما كسبت وهم لا يُظلمون. أفرأيت من جعل معبوده ما تهواه نفسه، فما هويت قولاً إلا قاله ولا عملاً إلا عمله ولا اعتقاداً إلا اعتقده، ضارباً بالعقل والشرع عرض الحائط؟ وأضلّه الله على علم منه سبق بأن هذا الإنسان لا يهتدي ولو جاءته كل آية، وختم على سمعه حسب سنته فأصبح لا يسمع الحق كأنه أصم، وعلى قلبه فلا يعقل معاني ما يسمع، وجعل على بصره ظلمة فلا يرى الأدلة الهادية، فمن يهديه من بعد الله؟ لا أحد؛ وسنة الله في الإضلال أن يُدعى العبد إلى الحق فيتكبّر ويسخر ويحارب فترة يصبح بعدها غير قابل للهداية. أفلا تتذكّرون أيها الناس فتؤمنوا وتوحّدوا وتعملوا الصالحات فتسعدوا في الدارين؟", "h": ["بطلان اعتقاد الكافرين في أن الناس يحيون ويموتون بلا جزاء على الكسب.", "تقرير البعث والجزاء.", "موعظة كبيرة في هذه الآية: «أم حسب الذين اجترحوا السيئات…» إلى آخرها، حتى إن أحد رجال السلف الصالح قام يتهجّد من الليل فقرأ حتى انتهى إلى هذه الآية، فأخذ يردّدها ويبكي.", "التنديد بالهوى والتحذير من اتباعه، فقد يُفضي بالعبد إلى ترك متابعة الهدى إلى مطاوعة الهوى، فيصبح معبوده هواه لا الرب تعالى مولاه.", "التحذير من ارتكاب سنن الضلال المفضي بالعبد إلى الضلال الذي لا هداية معه."], "k": "«أفرأيت من اتخذ إلهه هواه»… في أي أمر أطيع هواي وأترك ما أعرف أنه الحق؟"}, {"lbl": "الآيات ٢٤ – ٢٦", "q": "وَقَالُواْ مَا هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا يُهۡلِكُنَآ إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا يَظُنُّونَ ﴿٢٤﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ﴿٢٥﴾ قُلِ ٱللَّهُ يُحۡيِيكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يَجۡمَعُكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٢٦﴾", "w": [["وقالوا ما هي إلا حياتنا الدنيا", "قال منكرو البعث: ما الحياة إلا هذه، وليس وراءها حياة."], ["نموت ونحيا", "يموت بعضنا ويحيا بعضنا بأن يولدوا فيحيوا ويموتوا."], ["وما يهلكنا إلا الدهر", "وما يميتنا إلا مرور الزمان علينا."], ["وما لهم بذلك من علم", "ليس لهم أدنى علم على قولهم، لا من وحي وكتاب إلهي ولا من عقل."], ["إن هم إلا يظنون", "ما هم إلا يظنون فقط، والظن لا قيمة له ولا يُبنى عليه حكم."], ["وإذا تتلى عليهم آياتنا بيّنات", "إذا قُرئت عليهم الآيات الدالة على البعث والجزاء."], ["ما كان حجتهم", "لم تكن لهم من حجة إلا قولهم."], ["إلا أن قالوا ائتوا بآبائنا", "أحيوا لنا آباءنا الذين ماتوا وأتوا بهم إلينا."], ["قل الله يحييكم ثم يميتكم", "قل يا رسولنا: الله الذي أحياكم حين كنتم نطفاً ميتة ثم يميتكم."], ["ثم يجمعكم إلى يوم القيامة", "ثم بعد الموت يجمعكم إلى يوم القيامة للحساب والجزاء."], ["لا ريب فيه", "لا شك في مجيئه في وقته المحدد له."], ["ولكن أكثر الناس لا يعلمون", "لعدم تلقّيهم العلم عن الوحي الإلهي لكفرهم بالرسل والكتب."]], "m": "بعد بيان اعتقاد بعض المشركين في استواء حال المؤمنين والكافرين، حكى قول منكري البعث بالكلية ليردّ عليهم: وقالوا ما هناك إلا حياتنا هذه، نموت نحن الأحياء ويحيا أبناؤنا من بعدنا وهكذا تستمر الحياة، وما يفنينا إلا مرور الزمان؛ وهو إلحاد كامل وإنكار للخالق، وتناقض منهم، إذ إذا سُئلوا من خلقهم قالوا: الله، فينسبون إليه الخلق وهو أصعب، ولا ينسبون إليه الإماتة وهي أهون. فردّ تعالى مذهبهم الدهري: ما لهم بذلك من علم نقلي عن وحي، ولا عقلي عن عقل سليم لا يُنقض حكمه، إن هم إلا يظنون ويخرصون، وقضايا العقيدة لا تكون بالظن، والظن أكذب الحديث. وإذا قرأ عليهم رسول الله ﷺ آيات القرآن الدالة على البعث ما كانت لهم حجة يردّون بها إلا قولهم: أحيوا لنا آباءنا الذين ماتوا إن كنتم صادقين. فقال تعالى: قل لهم: الله يحييكم إذ كنتم نطفاً ميتة، ثم يميتكم بدون اختياركم، فالقادر على الإحياء والإماتة لا يُحيل العقل أن يحيي من أماتهم، وإنما لم يحيهم اليوم كما طلبتم لأنه لا فائدة منه، ولأنه يتنافى مع الحكمة العالية في خلق الحياتين، إذ خُلقوا ليعملوا ثم يُجازوا، ولهذا قال: ثم يجمعكم أحياء إلى يوم القيامة لا شك في مجيئه، ولكن أكثر الناس لا يعلمون، لأنهم لا يتفكّرون، ولأنهم بتكذيبهم بالوحي سدّوا في وجوههم طريق العلم الصحيح.", "h": ["تقرير البعث والجزاء.", "الرد على الدهريين، وهم الذين ينسبون الحياة والموت للدهر وينفون وجود الخالق عز وجل.", "بيان أن الكفار لا دليل لهم عقلي ولا نقلي على صحة الكفر، عقيدة كان أو عملاً.", "عدم إحياء الله تعالى لمن مات حين طالب به المكذّبون حتى يؤمنوا لم يكن عن عجز، بل لأنه يتنافى مع الحكمة التي دار عليها الكون كله.", "بيان أن أكثر الناس لا يعلمون، وذلك لأنهم كذّبوا بالوحي الإلهي في الكتاب والسنة.", "بيان أنه لا علم صحيح إلا من طريق الوحي الإلهي."], "k": "«وما يهلكنا إلا الدهر»… الأيام لا تفني، بل تقرّبني من لقاء ربي؛ فكيف أحسب أيامي؟"}, {"lbl": "الآيات ٢٧ – ٣٢", "q": "وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يَوۡمَئِذٖ يَخۡسَرُ ٱلۡمُبۡطِلُونَ ﴿٢٧﴾ وَتَرَىٰ كُلَّ أُمَّةٖ جَاثِيَةٗۚ كُلُّ أُمَّةٖ تُدۡعَىٰٓ إِلَىٰ كِتَٰبِهَا ٱلۡيَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٨﴾ هَٰذَا كِتَٰبُنَا يَنطِقُ عَلَيۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٩﴾ فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ﴿٣٠﴾ وَأَمَّا ٱلَّذِينَ كَفَرُوٓاْ أَفَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمٗا مُّجۡرِمِينَ ﴿٣١﴾ وَإِذَا قِيلَ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱلسَّاعَةُ لَا رَيۡبَ فِيهَا قُلۡتُم مَّا نَدۡرِي مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنّٗا وَمَا نَحۡنُ بِمُسۡتَيۡقِنِينَ ﴿٣٢﴾", "w": [["ولله ملك السماوات والأرض", "خلقاً وملكاً وتصرفاً، يفعل ما يشاء ويحكم ما يريد."], ["يخسر المبطلون", "يوم تقوم الساعة يخسر أصحاب الباطل بصيرورتهم إلى النار."], ["وترى كل أمة جاثية", "كل أمة ذات دين جاثية على ركبها تنتظر حكم الله فيها."], ["كل أمة تُدعى إلى كتابها", "إلى كتاب أعمالها، فإن كان خيراً فخير وإن كان شراً فشر."], ["اليوم تُجزون ما كنتم تعملون", "يقال لهم: اليوم تُجزون ما كنتم تعملون في الدنيا من خير وشر."], ["هذا كتابنا ينطق عليكم بالحق", "ديوان الحفظة الذي دوّنوا فيه أعمالكم شاهد عليكم بالحق."], ["إنا كنا نستنسخ ما كنتم تعملون", "نأمر بنسخ ما كنتم تعملون."], ["فيدخلهم ربهم في رحمته", "في جنته."], ["ذلك هو الفوز المبين", "الفوز البيّن الظاهر، وهو النجاة من النار ودخول الجنة."], ["أفلم تكن آياتي تتلى عليكم", "يقال لهم: ألم تأتكم رسلي فلم تكن آياتي تتلى عليكم؟"], ["فاستكبرتم وكنتم قوماً مجرمين", "عن آيات الله فلم تؤمنوا بها، وكنتم بذلك قوماً كافرين."], ["إن وعد الله حق", "بالبعث والجزاء العادل يوم القيامة حق ثابت."], ["إن نظن إلا ظناً وما نحن بمستيقنين", "ما كنا مستيقنين بالبعث، وإنما كنا نظنه ولا نجزم به."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: ولله ملك السماوات والأرض خلقاً وملكاً وتصرفاً، ومن كان هذا وصفه من القدرة والعلم لا يُنكر عليه بعث العباد بعد موتهم. ويوم تقوم الساعة يخسر المبطلون كل شيء حتى أنفسهم، يخسرون منازلهم في الجنة يرثها عنهم المؤمنون، ويرثون منازل المؤمنين في النار، ذلك هو الخسران المبين. وترى أيها الرسول يوم القيامة كل أهل دين وملة قد جثوا على ركبهم خوفاً وذلاً، كل أمة تُدعى إلى كتابها، ويقال لهم: اليوم تُجزون ما كنتم تعملون في الدنيا، فإذا حاولوا الإنكار قيل لهم: هذا كتاب الأعمال الذي دوّنته الحفظة ينطق عليكم بالحق، إنا كنا نأمر ملائكتنا بإثبات أعمالكم وحفظها، وها هي بين أيديكم. فأما الذين آمنوا وعملوا الصالحات وتركوا الشرك والمعاصي فيدخلهم ربهم في رحمته وهي الجنة، ذلك هو الفوز المبين، إذ الفوز النجاة من المرهوب والظفر بالمحبوب. وأما الذين كفروا فيقال لهم: ألم تأتكم رسلي فكانت آياتي تُتلى عليكم فاستكبرتم عنها، وكنتم باستكباركم قوماً مجرمين على أنفسكم؟ وإذا قيل لكم: إن وعد الله بالبعث حق والساعة آتية لا ريب فيها، قلتم متجاهلين متعجّبين: ما ندري ما الساعة، إن نظن إلا ظناً وما نحن بمستيقنين؛ وهذا حال كثير من الناس الذين يؤمنون بالله وبلقائه وهم لا يفترون عن المعاصي ولا يقصّرون عن فعل الشر.", "h": ["تقرير عقيدة البعث والجزاء بذكر بعض ما يقع يوم القيامة.", "تقرير عقيدة كتابة أعمال العباد وتقديمها لهم يوم القيامة في كتاب خاص.", "تقرير أن الإيمان والعمل الصالح سبب الفوز، وأن الشرك والمعاصي سبب الخسران.", "الظن في العقائد كالكفر بها، والعياذ بالله تعالى."], "k": "«هذا كتابنا ينطق عليكم بالحق»… لو قُرئ عليّ كتاب يومي هذا، ماذا كنت سأسمع؟"}, {"lbl": "الآيات ٣٣ – ٣٧", "q": "وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٣﴾ وَقِيلَ ٱلۡيَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِينَ ﴿٣٤﴾ ذَٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَايَٰتِ ٱللَّهِ هُزُوٗا وَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٣٥﴾ فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٣٦﴾ وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٣٧﴾", "w": [["وبدا لهم سيئات ما عملوا", "ظهر لهم يوم القيامة جزاء سيئات ما عملوه في الدنيا من الشرك والمعاصي."], ["وحاق بهم ما كانوا به يستهزئون", "نزل وأحاط بهم العذاب الذي كانوا يستهزئون به إذا خُوّفوا منه."], ["وقيل اليوم ننساكم", "قال الله تعالى لهم: اليوم نترككم في النار."], ["كما نسيتم لقاء يومكم هذا", "مثل ما نسيتم يومكم هذا فلم تعملوا له بما ينجي فيه."], ["ومأواكم النار", "محل إقامتكم النار."], ["وما لكم من ناصرين", "ينصرونكم بإخراجكم من النار."], ["ذلكم بأنكم اتخذتم آيات الله هزواً", "ذلكم العذاب بسبب كفركم واتخاذكم آيات الله شيئاً مهزوءاً به."], ["وغرّتكم الحياة الدنيا", "طول العمر والتمتع بالشهوات والمستلذّات."], ["ولا هم يُستعتبون", "لا يُؤذن لهم في الاستعتاب ليُعتبوا فيتوبوا."], ["فلله الحمد رب السماوات ورب الأرض", "فلله وحده الوصف بالجميل لإنجاز وعيده لأعدائه."], ["وله الكبرياء في السماوات والأرض", "العظمة والحكم النافذ الناجز على من شاء."], ["وهو العزيز الحكيم", "العزيز في انتقامه من أعدائه، الحكيم في تدبير خلقه."]], "m": "ما زال السياق في عرض مشاهد القيامة لعل السامعين يتعظون: وظهر للمشركين المكذبين بالبعث جزاء سيئات أعمالهم، وشاهدوا العذاب الذي كانوا إذا خُوّفوا منه استهزؤوا به، وقد نزل بساحتهم وأحاط بهم. وقال لهم الرب تعالى: اليوم نترككم في عذاب النار كما تركتم العمل المنجي من هذا العذاب، وهو الإيمان والعمل الصالح، ومأواكم النار وليس لكم من ينصركم فيخلّصكم منها. ذلكم الحكم بسبب اتخاذكم آيات الله الحاملة للحجج على وجوده ووجوب توحيده شيئاً مهزوءاً به، وغرّتكم الحياة الدنيا بزخرفها وطول أعماركم فيها فلم تؤمنوا. فاليوم لا يخرجون منها، وترك مخاطبتهم إشعاراً بأنه لا كرامة لهم، ولا يُطلب منهم أن يُرضوا ربهم بالتوبة، إذ لا توبة بعد الموت والرجوع إلى الدنيا غير ممكن، وهنا تعظم حسرتهم ويشتد كربهم. فلله الحمد رب السماوات ورب الأرض رب العالمين، حمد نفسه وقصر الحمد عليه بعد أن أنجز ما أوعد به الكافرين، وله العظمة والسلطان في السماوات والأرض، وهو العزيز الذي لا يُمانع ولا يُغالب، الحكيم الذي يضع كل شيء في موضعه، ويتجلّى ذلك في إكرام أوليائه برحمتهم وإهانة أعدائهم بتعذيبهم.", "h": ["بيان أن الاستهزاء بآيات الله وشرائعه كفر موجب للعذاب.", "تقرير قاعدة: الجزاء من جنس العمل، وكما يدين الفتى يُدان.", "مشروعية الحمد عند الفراغ من أي عمل صالح أو مباح."], "k": "«اليوم ننساكم كما نسيتم لقاء يومكم هذا»… ما الذي أنساه من لقاء ربي وسط مشاغلي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;